/** @type {import('next').NextConfig} */
const nextConfig = {
  transpilePackages: ['@cleano/shared-types', '@cleano/shared-utils', '@cleano/shared-constants'],
}

module.exports = nextConfig

module.exports = {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
}

export default function AuthLayout({
  children,
}: {
  children: React.ReactNode
}) {
  return <>{children}</>
}

'use client'

import { useState, useEffect, useRef, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { supabase } from '@/lib/supabase'

function FloatingIcon({ children, x, y, size, speed, delay, rotation }: {
  children: React.ReactNode; x: number; y: number; size: number; speed: number; delay: number; rotation: number
}) {
  return (
    <div
      className="floating-icon absolute pointer-events-none select-none"
      data-speed={speed}
      style={{
        left: `${x}%`,
        top: `${y}%`,
        width: size,
        height: size,
        animation: `float ${4 + speed * 2}s ease-in-out ${delay}s infinite`,
        opacity: 0,
        animationFillMode: 'forwards',
      }}
    >
      {children}
    </div>
  )
}

const TShirtSVG = ({ color = '#00AF5F', opacity = 0.15 }: { color?: string; opacity?: number }) => (
  <svg viewBox="0 0 64 64" fill="none" xmlns="http://www.w3.org/2000/svg">
    <path d="M20 8L8 16V28L16 26V56H48V26L56 28V16L44 8C44 8 40 14 32 14C24 14 20 8 20 8Z" stroke={color} strokeWidth="2" fill={color} fillOpacity={opacity} strokeLinecap="round" strokeLinejoin="round"/>
  </svg>
)

const HangerSVG = ({ color = '#8B5CF6', opacity = 0.12 }: { color?: string; opacity?: number }) => (
  <svg viewBox="0 0 64 64" fill="none" xmlns="http://www.w3.org/2000/svg">
    <path d="M32 8C32 8 28 8 28 12C28 16 32 16 32 16" stroke={color} strokeWidth="2" strokeLinecap="round"/>
    <path d="M32 16L8 40H56L32 16Z" stroke={color} strokeWidth="2" fill={color} fillOpacity={opacity} strokeLinecap="round" strokeLinejoin="round"/>
    <line x1="8" y1="40" x2="56" y2="40" stroke={color} strokeWidth="2.5" strokeLinecap="round"/>
  </svg>
)

const BubbleSVG = ({ color = '#00AF5F', opacity = 0.08 }: { color?: string; opacity?: number }) => (
  <svg viewBox="0 0 64 64" fill="none" xmlns="http://www.w3.org/2000/svg">
    <circle cx="32" cy="32" r="28" stroke={color} strokeWidth="1.5" fill={color} fillOpacity={opacity}/>
    <ellipse cx="22" cy="22" rx="8" ry="6" fill="white" fillOpacity="0.08" transform="rotate(-30 22 22)"/>
    <circle cx="18" cy="46" r="6" stroke={color} strokeWidth="1" fill={color} fillOpacity={opacity * 0.5}/>
    <circle cx="48" cy="18" r="4" stroke={color} strokeWidth="1" fill={color} fillOpacity={opacity * 0.5}/>
  </svg>
)

const IronSVG = ({ color = '#F59E0B', opacity = 0.12 }: { color?: string; opacity?: number }) => (
  <svg viewBox="0 0 64 64" fill="none" xmlns="http://www.w3.org/2000/svg">
    <path d="M16 24H48L52 44H8L16 24Z" stroke={color} strokeWidth="2" fill={color} fillOpacity={opacity} strokeLinecap="round" strokeLinejoin="round"/>
    <path d="M24 24V16C24 14 26 12 28 12H36C38 12 40 14 40 16V24" stroke={color} strokeWidth="2" strokeLinecap="round"/>
    <line x1="20" y1="36" x2="44" y2="36" stroke={color} strokeWidth="1.5" strokeLinecap="round" opacity="0.5"/>
  </svg>
)

const DropletSVG = ({ color = '#06B6D4', opacity = 0.1 }: { color?: string; opacity?: number }) => (
  <svg viewBox="0 0 64 64" fill="none" xmlns="http://www.w3.org/2000/svg">
    <path d="M32 6C32 6 12 30 12 42C12 53 21 58 32 58C43 58 52 53 52 42C52 30 32 6 32 6Z" stroke={color} strokeWidth="2" fill={color} fillOpacity={opacity} strokeLinecap="round" strokeLinejoin="round"/>
    <ellipse cx="24" cy="38" rx="5" ry="8" fill="white" fillOpacity="0.06" transform="rotate(-15 24 38)"/>
  </svg>
)

const SparklesSVG = ({ color = '#00AF5F', opacity = 0.15 }: { color?: string; opacity?: number }) => (
  <svg viewBox="0 0 64 64" fill="none" xmlns="http://www.w3.org/2000/svg">
    <path d="M32 4L36 24L56 20L40 32L56 44L36 40L32 60L28 40L8 44L24 32L8 20L28 24L32 4Z" stroke={color} strokeWidth="1.5" fill={color} fillOpacity={opacity} strokeLinejoin="round"/>
  </svg>
)

const WashingMachineSVG = () => (
  <svg viewBox="0 0 200 200" fill="none" xmlns="http://www.w3.org/2000/svg" className="w-full h-full">
    <rect x="20" y="10" width="160" height="180" rx="16" stroke="rgba(255,255,255,0.15)" strokeWidth="2" fill="rgba(255,255,255,0.03)"/>
    <rect x="30" y="20" width="140" height="40" rx="8" stroke="rgba(255,255,255,0.1)" strokeWidth="1.5" fill="rgba(255,255,255,0.02)"/>
    <circle cx="50" cy="40" r="6" fill="#00AF5F" fillOpacity="0.4"/>
    <circle cx="70" cy="40" r="6" fill="#8B5CF6" fillOpacity="0.3"/>
    <circle cx="90" cy="40" r="6" fill="#F59E0B" fillOpacity="0.3"/>
    <rect x="120" y="32" width="40" height="16" rx="4" stroke="rgba(255,255,255,0.1)" strokeWidth="1" fill="rgba(255,255,255,0.02)"/>
    <circle cx="100" cy="125" r="52" stroke="rgba(255,255,255,0.12)" strokeWidth="2" fill="rgba(255,255,255,0.02)"/>
    <circle cx="100" cy="125" r="40" stroke="rgba(0,175,95,0.2)" strokeWidth="1.5" fill="rgba(0,175,95,0.03)">
      <animateTransform attributeName="transform" type="rotate" values="0 100 125;360 100 125" dur="8s" repeatCount="indefinite"/>
    </circle>
    <path d="M80 110 Q90 130 100 115 Q110 100 120 120 Q130 140 115 135" stroke="rgba(0,175,95,0.25)" strokeWidth="2" fill="rgba(0,175,95,0.05)" strokeLinecap="round">
      <animateTransform attributeName="transform" type="rotate" values="0 100 125;360 100 125" dur="8s" repeatCount="indefinite"/>
    </path>
    <circle cx="100" cy="125" r="4" fill="rgba(255,255,255,0.08)">
      <animateTransform attributeName="transform" type="rotate" values="0 100 125;360 100 125" dur="8s" repeatCount="indefinite"/>
    </circle>
  </svg>
)

const features = [
  { icon: '⚡', title: 'Real-time Tracking', desc: 'Monitor every order from pickup to delivery in real-time' },
  { icon: '📊', title: 'Smart Analytics', desc: 'AI-powered insights to optimize your operations' },
  { icon: '🚀', title: 'Fleet Management', desc: 'Assign drivers and manage routes efficiently' },
  { icon: '💎', title: 'Premium Experience', desc: 'White-glove service management for your customers' },
]

export default function AdminLoginPage() {
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [showPassword, setShowPassword] = useState(false)
  const [activeFeature, setActiveFeature] = useState(0)
  const router = useRouter()
  const brandRef = useRef<HTMLDivElement>(null)
  const mouseRef = useRef({ x: 0.5, y: 0.5 })
  const rafRef = useRef<number>(0)

  useEffect(() => {
    const interval = setInterval(() => {
      setActiveFeature(prev => (prev + 1) % features.length)
    }, 3000)
    return () => clearInterval(interval)
  }, [])

  const handleMouseMove = useCallback((e: MouseEvent) => {
    mouseRef.current = {
      x: e.clientX / window.innerWidth,
      y: e.clientY / window.innerHeight,
    }
  }, [])

  useEffect(() => {
    window.addEventListener('mousemove', handleMouseMove)
    function animate() {
      const icons = brandRef.current?.querySelectorAll('.floating-icon')
      if (icons) {
        const mx = (mouseRef.current.x - 0.5) * 2
        const my = (mouseRef.current.y - 0.5) * 2
        icons.forEach((el) => {
          const speed = parseFloat((el as HTMLElement).dataset.speed || '1')
          const tx = mx * speed * 25
          const ty = my * speed * 18
          ;(el as HTMLElement).style.transform = `translate(${tx}px, ${ty}px)`
        })
      }
      rafRef.current = requestAnimationFrame(animate)
    }
    rafRef.current = requestAnimationFrame(animate)
    return () => {
      window.removeEventListener('mousemove', handleMouseMove)
      cancelAnimationFrame(rafRef.current)
    }
  }, [handleMouseMove])

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')
    if (!email.includes('@')) { setError('أدخل بريد إلكتروني صحيح'); return }
    if (!password) { setError('أدخل كلمة المرور'); return }

    setLoading(true)
    const { error: signInError } = await supabase.auth.signInWithPassword({ email, password })
    if (signInError) { setError(signInError.message); setLoading(false); return }

    const { data: { user } } = await supabase.auth.getUser()
    if (!user) { setError('حدث خطأ'); setLoading(false); return }

    const { data: profile } = await supabase.from('users').select('role, is_active').eq('id', user.id).single()
    const allowedRoles = ['admin', 'super_admin', 'manager', 'accountant']
    if (!allowedRoles.includes(profile?.role)) {
      await supabase.auth.signOut()
      setError('غير مصرح لك بالدخول — هذه اللوحة للمسؤولين فقط')
      setLoading(false)
      return
    }
    if (profile?.is_active === false) {
      await supabase.auth.signOut()
      setError('تم تعطيل حسابك — تواصل مع المسؤول')
      setLoading(false)
      return
    }

    setLoading(false)
    router.refresh()
    router.push('/')
  }

  return (
    <div className="min-h-screen flex flex-col lg:flex-row">
      <style jsx>{`
        @keyframes float {
          0%, 100% { opacity: 1; transform: translateY(0px); }
          50% { transform: translateY(-12px); }
        }
        @keyframes gradient-shift {
          0%, 100% { background-position: 0% 50%; }
          50% { background-position: 100% 50%; }
        }
        @keyframes fade-up {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .feature-enter {
          animation: fade-up 0.5s ease-out forwards;
        }
      `}</style>

      {/* Left side — Branding */}
      <div ref={brandRef} className="hidden lg:flex lg:w-[55%] relative overflow-hidden flex-col justify-between p-12"
        style={{
          background: 'linear-gradient(135deg, #0a1628 0%, #0e1f3d 30%, #12133a 60%, #0a1628 100%)',
        }}
      >
        <div className="absolute inset-0">
          <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-primary-500/[0.07] rounded-full blur-[120px]" />
          <div className="absolute bottom-0 left-0 w-[400px] h-[400px] bg-accent-purple/[0.06] rounded-full blur-[100px]" />
          <div className="absolute top-1/2 left-1/3 w-[300px] h-[300px] bg-cyan-500/[0.04] rounded-full blur-[80px]" />
        </div>

        {/* Floating icons */}
        <FloatingIcon x={5} y={8} size={48} speed={1.8} delay={0} rotation={-15}><TShirtSVG /></FloatingIcon>
        <FloatingIcon x={80} y={5} size={40} speed={1.2} delay={0.5} rotation={12}><HangerSVG /></FloatingIcon>
        <FloatingIcon x={8} y={75} size={36} speed={2.2} delay={1} rotation={20}><BubbleSVG /></FloatingIcon>
        <FloatingIcon x={85} y={70} size={44} speed={1.5} delay={0.3} rotation={-10}><IronSVG /></FloatingIcon>
        <FloatingIcon x={20} y={40} size={30} speed={2.5} delay={0.8} rotation={30}><DropletSVG /></FloatingIcon>
        <FloatingIcon x={75} y={35} size={34} speed={1.9} delay={1.2} rotation={-25}><SparklesSVG /></FloatingIcon>
        <FloatingIcon x={50} y={85} size={28} speed={1.4} delay={0.6} rotation={45}><DropletSVG color="#8B5CF6" opacity={0.08} /></FloatingIcon>
        <FloatingIcon x={90} y={50} size={32} speed={2.0} delay={0.9} rotation={-5}><TShirtSVG color="#8B5CF6" opacity={0.1} /></FloatingIcon>
        <FloatingIcon x={60} y={15} size={26} speed={1.6} delay={1.5} rotation={15}><BubbleSVG color="#06B6D4" opacity={0.06} /></FloatingIcon>

        {/* Top — Logo & tagline */}
        <div className="relative z-10">
          <div className="flex items-center gap-4 mb-2">
            <div className="w-12 h-12 bg-gradient-to-br from-primary-400 to-primary-600 rounded-2xl flex items-center justify-center shadow-glow-green">
              <span className="text-xl font-black text-white">LB</span>
            </div>
            <div>
              <h1 className="text-2xl font-bold text-white tracking-widest">Laundry Bag</h1>
              <p className="text-xs text-primary-400 font-medium tracking-wider">MANAGEMENT PLATFORM</p>
            </div>
          </div>
        </div>

        {/* Center — Washing machine + headline */}
        <div className="relative z-10 flex flex-col items-center -mt-8">
          <div className="w-52 h-52 mb-8">
            <WashingMachineSVG />
          </div>
          <h2 className="text-4xl font-bold text-white text-center leading-tight mb-3">
            The Future of<br />
            <span className="bg-gradient-to-r from-primary-400 via-emerald-300 to-cyan-400 bg-clip-text text-transparent">
              Laundry Operations
            </span>
          </h2>
          <p className="text-navy-300 text-center max-w-md text-sm leading-relaxed">
            Streamline your entire laundry business with our all-in-one platform.
            From order management to delivery tracking — everything in one place.
          </p>
        </div>

        {/* Bottom — Feature cards carousel */}
        <div className="relative z-10">
          <div className="grid grid-cols-2 gap-3">
            {features.map((f, i) => (
              <div
                key={i}
                className={`p-4 rounded-2xl border transition-all duration-500 ${
                  i === activeFeature
                    ? 'bg-white/[0.06] border-primary-500/30 shadow-[0_0_30px_-5px_rgba(0,175,95,0.15)]'
                    : 'bg-white/[0.02] border-white/[0.04] hover:bg-white/[0.04]'
                }`}
              >
                <span className="text-xl mb-2 block">{f.icon}</span>
                <h3 className={`text-sm font-semibold mb-1 transition-colors duration-500 ${
                  i === activeFeature ? 'text-primary-400' : 'text-white/80'
                }`}>{f.title}</h3>
                <p className="text-[11px] text-navy-400 leading-relaxed">{f.desc}</p>
              </div>
            ))}
          </div>

          {/* Progress dots */}
          <div className="flex justify-center gap-2 mt-5">
            {features.map((_, i) => (
              <button key={i} onClick={() => setActiveFeature(i)}
                className={`h-1.5 rounded-full transition-all duration-500 ${
                  i === activeFeature ? 'w-8 bg-primary-500' : 'w-1.5 bg-white/20 hover:bg-white/30'
                }`}
              />
            ))}
          </div>
        </div>
      </div>

      {/* Right side — Login form */}
      <div className="flex-1 flex items-center justify-center bg-navy-950 relative overflow-hidden min-h-screen lg:min-h-0">
        <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-navy-900/50 via-navy-950 to-navy-950 pointer-events-none" />
        <div className="absolute top-1/4 -right-20 w-72 h-72 bg-primary-500/[0.06] rounded-full blur-3xl pointer-events-none" />
        <div className="absolute bottom-1/4 -left-20 w-72 h-72 bg-accent-purple/[0.06] rounded-full blur-3xl pointer-events-none" />

        {/* Mobile branding (shown on small screens) */}
        <div className="lg:hidden absolute top-0 left-0 right-0 h-32 flex items-center justify-center"
          style={{ background: 'linear-gradient(to bottom, rgba(10,22,40,0.8), transparent)' }}>
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-gradient-to-br from-primary-400 to-primary-600 rounded-xl flex items-center justify-center shadow-glow-green">
              <span className="text-lg font-black text-white">LB</span>
            </div>
            <h1 className="text-xl font-bold text-white tracking-widest">Laundry Bag</h1>
          </div>
        </div>

        <div className="relative w-full max-w-sm px-6 animate-scale-in z-10">
          <div className="text-center mb-8 lg:mb-10">
            <div className="lg:hidden w-14 h-14 bg-gradient-to-br from-primary-400 to-primary-600 rounded-2xl flex items-center justify-center mx-auto mb-4 shadow-glow-green">
              <span className="text-xl font-black text-white">LB</span>
            </div>
            <h2 className="text-2xl font-bold text-white mb-1">Welcome back</h2>
            <p className="text-navy-400 text-sm">Sign in to your admin dashboard</p>
          </div>

          {error && (
            <div className="bg-red-500/10 border border-red-500/20 text-red-400 p-3 rounded-xl text-sm mb-4 text-center animate-slide-in">
              {error}
            </div>
          )}

          <form onSubmit={handleLogin} className="space-y-5">
            <div>
              <label className="block text-sm font-medium text-navy-300 mb-2">Email Address <span className="text-red-400">*</span></label>
              <input
                type="email"
                value={email}
                onChange={e => setEmail(e.target.value)}
                placeholder="admin@cleano.com"
                required
                className="w-full p-3.5 bg-navy-800/40 border border-navy-600/40 rounded-xl text-white placeholder-navy-500 focus:outline-none focus:ring-2 focus:ring-primary-500/40 focus:border-primary-500/40 transition-all"
                dir="ltr"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-navy-300 mb-2">Password <span className="text-red-400">*</span></label>
              <div className="relative">
                <input
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  onChange={e => setPassword(e.target.value)}
                  placeholder="••••••••"
                  required
                  minLength={6}
                  className="w-full p-3.5 pr-12 bg-navy-800/40 border border-navy-600/40 rounded-xl text-white placeholder-navy-500 focus:outline-none focus:ring-2 focus:ring-primary-500/40 focus:border-primary-500/40 transition-all"
                  dir="ltr"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-navy-400 hover:text-white transition-colors text-lg"
                >
                  {showPassword ? '🙈' : '👁️'}
                </button>
              </div>
            </div>
            <button
              type="submit"
              disabled={loading}
              className="w-full bg-gradient-to-r from-primary-500 to-primary-600 text-white p-3.5 rounded-xl text-base font-semibold hover:shadow-glow-green disabled:opacity-50 transition-all duration-300 mt-2"
            >
              {loading ? (
                <span className="flex items-center justify-center gap-2">
                  <svg className="animate-spin h-5 w-5" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="3" fill="none" strokeDasharray="31.4" strokeLinecap="round"><animateTransform attributeName="transform" type="rotate" values="0 12 12;360 12 12" dur="1s" repeatCount="indefinite"/></circle></svg>
                  Signing in...
                </span>
              ) : 'Sign In'}
            </button>
          </form>

          <div className="mt-8 pt-6 border-t border-white/[0.04]">
            <p className="text-center text-navy-500 text-xs">
              Powered by <span className="text-primary-500 font-semibold">Laundry Bag</span> Platform
            </p>
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { supabase } from '@/lib/supabase'
import { motion } from 'framer-motion'
import Badge from '@/components/ui/Badge'
import {
  ScrollText, ShoppingBag, Users, Crown, Settings, Search,
  ArrowRightLeft, UserPlus, UserMinus, Truck, Plus, Edit2, Trash2, Power, Filter,
  ChevronRight, ChevronLeft,
} from 'lucide-react'
import PermissionGate from '@/components/ui/PermissionGate'
import { TableSkeleton } from '@/components/ui/Skeleton'

interface AuditLog {
  id: string
  user_id: string
  action: string
  entity_type: string
  entity_id: string | null
  details: any
  created_at: string
  actor?: { name: string; avatar_url?: string | null; role: string } | null
}

const actionConfig: Record<string, { label: string; icon: typeof Plus; variant: 'success' | 'warning' | 'danger' | 'info' | 'purple' | 'neutral' }> = {
  create: { label: 'إنشاء', icon: Plus, variant: 'success' },
  update: { label: 'تعديل', icon: Edit2, variant: 'info' },
  delete: { label: 'حذف', icon: Trash2, variant: 'danger' },
  status_change: { label: 'تغيير حالة', icon: ArrowRightLeft, variant: 'purple' },
  assign_driver: { label: 'تعيين سائق', icon: Truck, variant: 'info' },
  toggle_active: { label: 'تفعيل/إلغاء', icon: Power, variant: 'warning' },
  change_role: { label: 'تغيير صلاحية', icon: Settings, variant: 'purple' },
}

const entityConfig: Record<string, { label: string; icon: typeof ShoppingBag }> = {
  order: { label: 'طلب', icon: ShoppingBag },
  user: { label: 'مستخدم', icon: Users },
  plan: { label: 'باقة', icon: Crown },
}

function timeAgo(dateStr: string): string {
  const diff = Date.now() - new Date(dateStr).getTime()
  const mins = Math.floor(diff / 60000)
  if (mins < 1) return 'الآن'
  if (mins < 60) return `منذ ${mins} دقيقة`
  const hours = Math.floor(mins / 60)
  if (hours < 24) return `منذ ${hours} ساعة`
  const days = Math.floor(hours / 24)
  return `منذ ${days} يوم`
}

function fullDateTime(dateStr: string): string {
  const d = new Date(dateStr)
  return d.toLocaleDateString('ar-EG', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }) +
    ' — ' + d.toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit', second: '2-digit' })
}

function buildDescription(log: AuditLog): string {
  const d = log.details || {}
  switch (log.action) {
    case 'create':
      if (log.entity_type === 'order') return `أنشأ طلب ${d.order_number || ''} بقيمة ${d.total || 0} ج.م`
      if (log.entity_type === 'user') return `أضاف مستخدم "${d.name}" بدور ${d.role}`
      if (log.entity_type === 'plan') return `أنشأ باقة "${d.name}" بسعر ${d.price} ج.م`
      return 'إنشاء عنصر جديد'
    case 'status_change':
      return `غيّر حالة الطلب ${d.order_number || ''} من "${d.from}" إلى "${d.to}"`
    case 'assign_driver':
      return `عيّن سائق للطلب ${d.order_number || ''}`
    case 'toggle_active':
      return `${d.is_active ? 'فعّل' : 'ألغى تفعيل'} المستخدم "${d.name}"`
    case 'change_role':
      return `غيّر صلاحية "${d.name}" من ${d.from} إلى ${d.to}`
    case 'update':
      if (log.entity_type === 'plan') return `عدّل الباقة "${d.name}"`
      return 'تعديل عنصر'
    case 'delete':
      if (log.entity_type === 'order') return `حذف الطلب ${d.order_number || ''}`
      if (log.entity_type === 'plan') return `حذف الباقة "${d.name}"`
      return 'حذف عنصر'
    default:
      return log.action
  }
}

const PAGE_SIZE = 20

export default function AuditPage() {
  const [logs, setLogs] = useState<AuditLog[]>([])
  const [loading, setLoading] = useState(true)
  const [search, setSearch] = useState('')
  const [entityFilter, setEntityFilter] = useState('all')
  const [actionFilter, setActionFilter] = useState('all')
  const [roleFilter, setRoleFilter] = useState('all')
  const [page, setPage] = useState(0)
  const [totalCount, setTotalCount] = useState(0)

  useEffect(() => { loadLogs() }, [page, entityFilter, actionFilter])

  async function loadLogs() {
    setLoading(true)
    let query = supabase
      .from('audit_logs')
      .select('id, user_id, action, entity_type, entity_id, details, created_at, actor:users!audit_logs_user_id_fkey(name, role)', { count: 'exact' })
      .order('created_at', { ascending: false })

    if (entityFilter !== 'all') query = query.eq('entity_type', entityFilter)
    if (actionFilter !== 'all') query = query.eq('action', actionFilter)

    query = query.range(page * PAGE_SIZE, (page + 1) * PAGE_SIZE - 1)

    const { data, error, count } = await query

    if (error) { console.error('audit_logs error:', error); setLoading(false); return }

    const normalized = (data ?? []).map((d: any) => ({
      ...d,
      actor: Array.isArray(d.actor) ? d.actor[0] ?? null : d.actor,
    }))
    setLogs(normalized)
    setTotalCount(count ?? 0)
    setLoading(false)
  }

  const filtered = logs.filter(log => {
    if (roleFilter !== 'all' && (log.actor?.role || '') !== roleFilter) return false
    if (search) {
      const s = search.toLowerCase()
      const desc = buildDescription(log).toLowerCase()
      const actorName = (log.actor?.name || '').toLowerCase()
      if (!desc.includes(s) && !actorName.includes(s)) return false
    }
    return true
  })

  const totalPages = Math.ceil(totalCount / PAGE_SIZE)

  return (
    <PermissionGate permission="audit.view">
    <div className="space-y-5">
      <motion.div initial={{ opacity: 0, y: -5 }} animate={{ opacity: 1, y: 0 }} className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
            <ScrollText className="w-5 h-5 text-primary-500" /> سجل النشاطات
          </h2>
          <p className="text-sm text-gray-400 mt-0.5">تتبع جميع العمليات التي تتم على النظام</p>
        </div>
        <div className="text-sm text-gray-400">{totalCount} سجل</div>
      </motion.div>

      {/* Filters */}
      <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.1 }} className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search size={16} className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400" />
          <input type="text" placeholder="بحث بالاسم أو العملية..." value={search} onChange={e => setSearch(e.target.value)}
            className="w-full pr-10 pl-4 py-2.5 bg-white border border-surface-border/60 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/15 focus:border-primary-500/30 transition-all" />
        </div>
        <select value={entityFilter} onChange={e => { setEntityFilter(e.target.value); setPage(0) }}
          className="px-3 py-2.5 bg-white border border-surface-border/60 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/15 transition-all">
          <option value="all">كل الأقسام</option>
          <option value="order">طلب</option>
          <option value="user">مستخدم</option>
          <option value="plan">باقة</option>
        </select>
        <select value={actionFilter} onChange={e => { setActionFilter(e.target.value); setPage(0) }}
          className="px-3 py-2.5 bg-white border border-surface-border/60 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/15 transition-all">
          <option value="all">كل العمليات</option>
          <option value="create">إنشاء</option>
          <option value="update">تعديل</option>
          <option value="delete">حذف</option>
          <option value="status_change">تغيير حالة</option>
          <option value="assign_driver">تعيين سائق</option>
          <option value="toggle_active">تفعيل/إلغاء</option>
        </select>
        <select value={roleFilter} onChange={e => setRoleFilter(e.target.value)}
          className="px-3 py-2.5 bg-white border border-surface-border/60 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/15 transition-all">
          <option value="all">كل المستخدمين</option>
          <option value="admin">المديرين</option>
          <option value="super_admin">المدير العام</option>
          <option value="manager">المشرفين</option>
          <option value="driver">السائقين</option>
          <option value="customer">العملاء</option>
        </select>
      </motion.div>

      {/* Timeline */}
      {loading ? (
        <TableSkeleton rows={6} cols={4} />
      ) : filtered.length === 0 ? (
        <div className="bg-white rounded-2xl shadow-premium border border-surface-border/60 p-12 text-center">
          <div className="w-16 h-16 rounded-2xl bg-surface-muted flex items-center justify-center mx-auto mb-4">
            <ScrollText size={28} className="text-gray-300" />
          </div>
          <h3 className="font-semibold text-gray-800 mb-1">لا توجد سجلات</h3>
          <p className="text-sm text-gray-400">ستظهر هنا جميع العمليات التي تتم على النظام</p>
        </div>
      ) : (
        <div className="bg-white rounded-2xl shadow-premium border border-surface-border/60 overflow-hidden">
          <div className="divide-y divide-surface-border/40">
            {filtered.map((log, i) => {
              const ac = actionConfig[log.action] || { label: log.action, icon: Settings, variant: 'neutral' as const }
              const ec = entityConfig[log.entity_type] || { label: log.entity_type, icon: Settings }
              const ActionIcon = ac.icon
              const EntityIcon = ec.icon

              return (
                <motion.div
                  key={log.id}
                  initial={{ opacity: 0, x: 10 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: Math.min(i * 0.02, 0.5) }}
                  className="flex items-start gap-4 px-5 py-4 hover:bg-surface-muted/30 transition-colors"
                >
                  <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-primary-400 to-accent-purple/80 flex items-center justify-center text-white font-bold text-sm flex-shrink-0 mt-0.5 overflow-hidden">
                    {log.actor?.avatar_url ? (
                      <img src={log.actor.avatar_url} alt="" className="w-full h-full object-cover" />
                    ) : (
                      log.actor?.name?.[0] ?? '?'
                    )}
                  </div>

                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap mb-1.5">
                      <span className="font-bold text-sm text-gray-800">{log.actor?.name ?? 'نظام'}</span>
                      {log.actor?.role && (
                        <span className={`text-[10px] px-2 py-0.5 rounded-full font-semibold ${
                          log.actor.role === 'admin' || log.actor.role === 'super_admin' ? 'bg-purple-100 text-purple-600' :
                          log.actor.role === 'driver' ? 'bg-emerald-100 text-emerald-600' :
                          log.actor.role === 'customer' ? 'bg-blue-100 text-blue-600' :
                          log.actor.role === 'manager' ? 'bg-amber-100 text-amber-600' :
                          'bg-gray-100 text-gray-600'
                        }`}>
                          {log.actor.role === 'admin' ? 'مدير' : log.actor.role === 'super_admin' ? 'مدير عام' :
                           log.actor.role === 'driver' ? 'سائق' : log.actor.role === 'customer' ? 'عميل' :
                           log.actor.role === 'manager' ? 'مشرف' : log.actor.role === 'accountant' ? 'محاسب' : log.actor.role}
                        </span>
                      )}
                      <Badge variant={ac.variant}>
                        <ActionIcon size={10} className="ml-1" />
                        {ac.label}
                      </Badge>
                      <span className="text-xs text-gray-400 flex items-center gap-1">
                        <EntityIcon size={12} /> {ec.label}
                      </span>
                    </div>
                    <p className="text-sm text-gray-600 leading-relaxed mb-1.5">{buildDescription(log)}</p>
                    <div className="flex items-center gap-3">
                      <p className="text-[11px] text-gray-400">{fullDateTime(log.created_at)}</p>
                      <span className="text-[10px] text-primary-500 font-medium">({timeAgo(log.created_at)})</span>
                    </div>
                  </div>
                </motion.div>
              )
            })}
          </div>

          {/* Pagination */}
          {totalPages > 1 && (
            <div className="flex items-center justify-between px-5 py-3 border-t border-surface-border/40">
              <span className="text-xs text-gray-400">
                صفحة {page + 1} من {totalPages}
              </span>
              <div className="flex items-center gap-1">
                <button
                  onClick={() => setPage(p => p - 1)}
                  disabled={page === 0}
                  className="p-2 rounded-lg hover:bg-surface-muted disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
                >
                  <ChevronRight size={16} className="text-gray-600" />
                </button>
                {Array.from({ length: Math.min(totalPages, 5) }, (_, i) => {
                  let pageNum: number
                  if (totalPages <= 5) {
                    pageNum = i
                  } else if (page < 3) {
                    pageNum = i
                  } else if (page > totalPages - 4) {
                    pageNum = totalPages - 5 + i
                  } else {
                    pageNum = page - 2 + i
                  }
                  return (
                    <button
                      key={pageNum}
                      onClick={() => setPage(pageNum)}
                      className={`w-8 h-8 rounded-lg text-xs font-medium transition-all ${
                        page === pageNum
                          ? 'bg-navy-900 text-white shadow-premium-md'
                          : 'text-gray-500 hover:bg-surface-muted'
                      }`}
                    >
                      {pageNum + 1}
                    </button>
                  )
                })}
                <button
                  onClick={() => setPage(p => p + 1)}
                  disabled={page >= totalPages - 1}
                  className="p-2 rounded-lg hover:bg-surface-muted disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
                >
                  <ChevronLeft size={16} className="text-gray-600" />
                </button>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
    </PermissionGate>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { supabase } from '@/lib/supabase'
import DataTable from '@/components/ui/DataTable'
import Badge from '@/components/ui/Badge'
import Modal from '@/components/ui/Modal'
import { MapPin, Plus, Edit2, Power } from 'lucide-react'
import { motion } from 'framer-motion'
import { useToast } from '@/components/ui/Toast'
import Tooltip from '@/components/ui/Tooltip'
import PermissionGate from '@/components/ui/PermissionGate'

export default function BranchesPage() {
  const [branches, setBranches] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [showAdd, setShowAdd] = useState(false)
  const [editItem, setEditItem] = useState<any>(null)
  const [saving, setSaving] = useState(false)
  const [form, setForm] = useState({ name: '', address: '', phone: '' })
  const { toast } = useToast()

  useEffect(() => { loadBranches() }, [])

  async function loadBranches() {
    const { data } = await supabase.from('branches').select('id, name, address, phone, is_active, created_at').order('created_at', { ascending: false })
    setBranches(data ?? [])
    setLoading(false)
  }

  async function handleAdd(e: React.FormEvent) {
    e.preventDefault()
    setSaving(true)
    const { error } = await supabase.from('branches').insert({ ...form, is_active: true })
    setSaving(false)
    if (!error) { setShowAdd(false); setForm({ name: '', address: '', phone: '' }); loadBranches(); toast('تم إضافة الفرع بنجاح') }
    else { toast('حدث خطأ أثناء الإضافة', 'error') }
  }

  async function handleEdit(e: React.FormEvent) {
    e.preventDefault()
    setSaving(true)
    const { error } = await supabase.from('branches').update({ name: form.name, address: form.address, phone: form.phone }).eq('id', editItem.id)
    setSaving(false)
    if (!error) { setEditItem(null); loadBranches(); toast('تم تعديل الفرع') }
    else { toast('حدث خطأ أثناء التعديل', 'error') }
  }

  async function toggleActive(id: string, current: boolean) {
    await supabase.from('branches').update({ is_active: !current }).eq('id', id)
    loadBranches()
    toast(current ? 'تم تعطيل الفرع' : 'تم تفعيل الفرع')
  }

  function openEdit(item: any) {
    setForm({ name: item.name, address: item.address ?? '', phone: item.phone ?? '' })
    setEditItem(item)
  }

  const columns = [
    { key: 'name', label: 'اسم الفرع', render: (item: any) => <span className="font-semibold">{item.name}</span> },
    { key: 'address', label: 'العنوان', render: (item: any) => item.address ?? '—' },
    { key: 'phone', label: 'الهاتف', render: (item: any) => <span dir="ltr">{item.phone ?? '—'}</span> },
    { key: 'is_active', label: 'الحالة', render: (item: any) => <Badge variant={item.is_active ? 'success' : 'danger'}>{item.is_active ? 'نشط' : 'معطل'}</Badge> },
    { key: 'actions', label: '', render: (item: any) => (
      <div className="flex gap-1">
        <Tooltip content="تعديل"><button onClick={() => openEdit(item)} className="p-1.5 hover:bg-surface-muted rounded-lg transition-colors"><Edit2 size={14} className="text-gray-500" /></button></Tooltip>
        <Tooltip content={item.is_active ? 'تعطيل' : 'تفعيل'}><button onClick={() => toggleActive(item.id, item.is_active)} className="p-1.5 hover:bg-surface-muted rounded-lg transition-colors"><Power size={14} className={item.is_active ? 'text-red-400' : 'text-green-500'} /></button></Tooltip>
      </div>
    )},
  ]

  const formFields = (
    <>
      <div>
        <label className="block text-xs font-medium text-gray-500 mb-1.5">اسم الفرع <span className="text-red-400">*</span></label>
        <input type="text" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} required
          className="w-full p-3 border border-surface-border rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/15 focus:border-primary-500/30 transition-all" />
      </div>
      <div>
        <label className="block text-xs font-medium text-gray-500 mb-1.5">العنوان <span className="text-red-400">*</span></label>
        <input type="text" value={form.address} onChange={e => setForm({ ...form, address: e.target.value })} required
          className="w-full p-3 border border-surface-border rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/15 focus:border-primary-500/30 transition-all" />
      </div>
      <div>
        <label className="block text-xs font-medium text-gray-500 mb-1.5">الهاتف</label>
        <input type="tel" value={form.phone} onChange={e => setForm({ ...form, phone: e.target.value })} dir="ltr"
          className="w-full p-3 border border-surface-border rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/15 focus:border-primary-500/30 transition-all" />
      </div>
    </>
  )

  return (
    <PermissionGate permission="settings.view">
    <div className="space-y-6">
      <motion.div initial={{ opacity: 0, y: -5 }} animate={{ opacity: 1, y: 0 }} className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2"><MapPin className="w-5 h-5 text-blue-500" /> إدارة الفروع</h2>
          <p className="text-sm text-gray-400 mt-0.5">{branches.length} فرع</p>
        </div>
        <button onClick={() => { setForm({ name: '', address: '', phone: '' }); setShowAdd(true) }}
          className="flex items-center gap-2 bg-gradient-to-l from-primary-500 to-primary-600 text-white px-4 py-2.5 rounded-xl text-sm font-medium hover:shadow-glow-green transition-all duration-300">
          <Plus size={16} /> فرع جديد
        </button>
      </motion.div>

      {loading ? <div className="flex items-center justify-center h-32"><div className="w-6 h-6 border-3 border-primary-500 border-t-transparent rounded-full animate-spin" /></div>
        : <DataTable columns={columns} data={branches} emptyMessage="لا توجد فروع" />}

      <Modal open={showAdd} onClose={() => setShowAdd(false)} title="فرع جديد">
        <form onSubmit={handleAdd} className="space-y-4">
          {formFields}
          <button type="submit" disabled={saving} className="w-full bg-gradient-to-l from-primary-500 to-primary-600 text-white p-3 rounded-xl font-semibold hover:shadow-glow-green disabled:opacity-50 transition-all">
            {saving ? 'جاري الحفظ...' : 'إضافة الفرع'}
          </button>
        </form>
      </Modal>

      <Modal open={!!editItem} onClose={() => setEditItem(null)} title="تعديل الفرع">
        <form onSubmit={handleEdit} className="space-y-4">
          {formFields}
          <button type="submit" disabled={saving} className="w-full bg-gradient-to-l from-primary-500 to-primary-600 text-white p-3 rounded-xl font-semibold hover:shadow-glow-green disabled:opacity-50 transition-all">
            {saving ? 'جاري الحفظ...' : 'حفظ التعديلات'}
          </button>
        </form>
      </Modal>
    </div>
    </PermissionGate>
  )
}

'use client'

import { useEffect, useState, useMemo } from 'react'
import { motion } from 'framer-motion'
import { supabase } from '@/lib/supabase'
import DataTable from '@/components/ui/DataTable'
import Badge from '@/components/ui/Badge'
import Modal from '@/components/ui/Modal'
import { Search, Plus, Edit2, Power, Users } from 'lucide-react'
import { TableSkeleton } from '@/components/ui/Skeleton'
import { useToast } from '@/components/ui/Toast'
import Tooltip from '@/components/ui/Tooltip'
import PermissionGate from '@/components/ui/PermissionGate'
import { isValidEgyptianPhone, isValidEmail } from '@/lib/utils'

export default function CustomersPage() {
  const [customers, setCustomers] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [search, setSearch] = useState('')
  const [showAdd, setShowAdd] = useState(false)
  const [editItem, setEditItem] = useState<any>(null)
  const [saving, setSaving] = useState(false)
  const [form, setForm] = useState({ name: '', phone: '', email: '', tier: 'bronze' })
  const [page, setPage] = useState(0)
  const [totalCount, setTotalCount] = useState(0)
  const { toast } = useToast()
  const PAGE_SIZE = 20

  useEffect(() => { loadCustomers() }, [page])

  async function loadCustomers() {
    const { data, count } = await supabase.from('users')
      .select('id, name, phone, email, customer_code, tier, points, is_active, created_at', { count: 'exact' })
      .eq('role', 'customer').order('created_at', { ascending: false })
      .range(page * PAGE_SIZE, (page + 1) * PAGE_SIZE - 1)
    setCustomers(data ?? [])
    setTotalCount(count ?? 0)
    setLoading(false)
  }

  async function handleAdd(e: React.FormEvent) {
    e.preventDefault()
    if (form.phone && !isValidEgyptianPhone(form.phone)) { toast('رقم الموبايل غير صحيح — يجب أن يبدأ بـ 01 ويكون 11 رقم', 'error'); return }
    if (form.email && !isValidEmail(form.email)) { toast('صيغة البريد الإلكتروني غير صحيحة', 'error'); return }
    setSaving(true)
    const res = await fetch('/api/users', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...form, role: 'customer' }),
    })
    const result = await res.json()
    setSaving(false)
    if (result.success) { setShowAdd(false); setForm({ name: '', phone: '', email: '', tier: 'bronze' }); loadCustomers(); toast('تم إضافة العميل بنجاح') }
    else { toast(result.error ?? 'حدث خطأ أثناء الإضافة', 'error') }
  }

  async function handleEdit(e: React.FormEvent) {
    e.preventDefault()
    if (form.phone && !isValidEgyptianPhone(form.phone)) { toast('رقم الموبايل غير صحيح — يجب أن يبدأ بـ 01 ويكون 11 رقم', 'error'); return }
    if (form.email && !isValidEmail(form.email)) { toast('صيغة البريد الإلكتروني غير صحيحة', 'error'); return }
    setSaving(true)
    if (form.phone) {
      const { data: dup } = await supabase.from('users').select('id').eq('phone', form.phone).neq('id', editItem.id).maybeSingle()
      if (dup) { setSaving(false); toast('رقم الموبايل مستخدم بالفعل', 'error'); return }
    }
    if (form.email) {
      const { data: dup } = await supabase.from('users').select('id').eq('email', form.email).neq('id', editItem.id).maybeSingle()
      if (dup) { setSaving(false); toast('البريد الإلكتروني مستخدم بالفعل', 'error'); return }
    }
    const { error } = await supabase.from('users').update({ name: form.name, phone: form.phone, email: form.email, tier: form.tier }).eq('id', editItem.id)
    setSaving(false)
    if (!error) { setEditItem(null); loadCustomers(); toast('تم تعديل بيانات العميل') }
    else { toast('حدث خطأ أثناء التعديل', 'error') }
  }

  async function toggleActive(id: string, current: boolean) {
    setCustomers(prev => prev.map(c => c.id === id ? { ...c, is_active: !current } : c))
    toast(current ? 'تم تعطيل العميل' : 'تم تفعيل العميل')
    const { error } = await supabase.from('users').update({ is_active: !current }).eq('id', id)
    if (error) { toast('حدث خطأ — جاري التحديث', 'error'); loadCustomers() }
  }

  function openEdit(item: any) {
    setForm({ name: item.name, phone: item.phone ?? '', email: item.email ?? '', tier: item.tier ?? 'bronze' })
    setEditItem(item)
  }

  const filtered = useMemo(() => customers.filter(c => {
    if (!search) return true
    const s = search.toLowerCase()
    return c.name?.toLowerCase().includes(s) || c.phone?.includes(s) || c.customer_code?.toLowerCase().includes(s)
  }), [customers, search])

  const tierVariant = (tier: string) => {
    const map: Record<string, 'success' | 'warning' | 'info' | 'purple'> = { bronze: 'warning', silver: 'info', gold: 'success', platinum: 'purple' }
    return map[tier] ?? 'info'
  }
  const tierLabel: Record<string, string> = { bronze: 'برونزي', silver: 'فضي', gold: 'ذهبي', platinum: 'بلاتيني' }

  const columns = [
    { key: 'customer_code', label: 'الكود', render: (item: any) => <span className="font-bold text-primary-600 text-xs">{item.customer_code}</span> },
    { key: 'name', label: 'الاسم', render: (item: any) => (
      <div className="flex items-center gap-3">
        <div className="w-8 h-8 rounded-xl bg-gradient-to-br from-navy-400 to-accent-purple/80 flex items-center justify-center text-white text-xs font-bold shadow-premium">{item.name?.[0]}</div>
        <span className="font-medium">{item.name}</span>
      </div>
    )},
    { key: 'phone', label: 'الهاتف' },
    { key: 'email', label: 'البريد', render: (item: any) => item.email ?? <span className="text-gray-300">—</span> },
    { key: 'tier', label: 'المستوى', render: (item: any) => <Badge variant={tierVariant(item.tier)}>{tierLabel[item.tier] ?? item.tier}</Badge> },
    { key: 'points', label: 'النقاط', render: (item: any) => <span className="font-semibold">{item.points}</span> },
    { key: 'is_active', label: 'الحالة', render: (item: any) => <Badge variant={item.is_active ? 'success' : 'danger'}>{item.is_active ? 'نشط' : 'معطل'}</Badge> },
