}

'use client'

import { useEffect, useState } from 'react'
import { motion } from 'framer-motion'
import { supabase } from '@/lib/supabase'
import DataTable from '@/components/ui/DataTable'
import Badge from '@/components/ui/Badge'
import Modal from '@/components/ui/Modal'
import StatCard from '@/components/ui/StatCard'
import { Search, Plus, Edit2, Power, Eye, Truck, CheckCircle, Clock, XCircle } from 'lucide-react'
import { TableSkeleton } from '@/components/ui/Skeleton'
import { useToast } from '@/components/ui/Toast'
import Tooltip from '@/components/ui/Tooltip'
import PermissionGate from '@/components/ui/PermissionGate'
import { isValidEgyptianPhone, isValidEmail } from '@/lib/utils'

const PAGE_SIZE = 20

export default function DriversPage() {
  const [drivers, setDrivers] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [search, setSearch] = useState('')
  const [showAdd, setShowAdd] = useState(false)
  const [editItem, setEditItem] = useState<any>(null)
  const [detailItem, setDetailItem] = useState<any>(null)
  const [saving, setSaving] = useState(false)
  const [form, setForm] = useState({ name: '', phone: '', email: '', vehicle_type: 'motorcycle', vehicle_number: '' })
  const [page, setPage] = useState(0)
  const [totalCount, setTotalCount] = useState(0)
  const { toast } = useToast()

  useEffect(() => { loadDrivers() }, [page, search])

  async function loadDrivers() {
    setLoading(true)
    const from = page * PAGE_SIZE
    const to = from + PAGE_SIZE - 1
    let query = supabase.from('users').select('id, name, phone, email, vehicle_type, vehicle_number, is_active, created_at', { count: 'exact' }).eq('role', 'driver')
    if (search) {
      query = query.or(`name.ilike.%${search}%,phone.ilike.%${search}%`)
    }
    const { data, count } = await query.order('created_at', { ascending: false }).range(from, to)
    setDrivers(data ?? [])
    setTotalCount(count ?? 0)
    setLoading(false)
  }

  async function handleAdd(e: React.FormEvent) {
    e.preventDefault()
    if (form.phone && !isValidEgyptianPhone(form.phone)) { toast('رقم الموبايل غير صحيح — يجب أن يبدأ بـ 01 ويكون 11 رقم', 'error'); return }
    if (form.email && !isValidEmail(form.email)) { toast('صيغة البريد الإلكتروني غير صحيحة', 'error'); return }
    setSaving(true)
    const res = await fetch('/api/users', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...form, role: 'driver' }),
    })
    const result = await res.json()
    setSaving(false)
    if (result.success) { setShowAdd(false); setForm({ name: '', phone: '', email: '', vehicle_type: 'motorcycle', vehicle_number: '' }); loadDrivers(); toast('تم إضافة السائق بنجاح') }
    else { toast(result.error ?? 'حدث خطأ أثناء الإضافة', 'error') }
  }

  async function handleEdit(e: React.FormEvent) {
    e.preventDefault()
    if (form.phone && !isValidEgyptianPhone(form.phone)) { toast('رقم الموبايل غير صحيح — يجب أن يبدأ بـ 01 ويكون 11 رقم', 'error'); return }
    if (form.email && !isValidEmail(form.email)) { toast('صيغة البريد الإلكتروني غير صحيحة', 'error'); return }
    setSaving(true)
    if (form.phone) {
      const { data: dup } = await supabase.from('users').select('id').eq('phone', form.phone).neq('id', editItem.id).maybeSingle()
      if (dup) { setSaving(false); toast('رقم الموبايل مستخدم بالفعل', 'error'); return }
    }
    if (form.email) {
      const { data: dup } = await supabase.from('users').select('id').eq('email', form.email).neq('id', editItem.id).maybeSingle()
      if (dup) { setSaving(false); toast('البريد الإلكتروني مستخدم بالفعل', 'error'); return }
    }
    const { error } = await supabase.from('users').update({ name: form.name, phone: form.phone, email: form.email, vehicle_type: form.vehicle_type, vehicle_number: form.vehicle_number }).eq('id', editItem.id)
    setSaving(false)
    if (!error) { setEditItem(null); loadDrivers(); toast('تم تعديل بيانات السائق') }
    else { toast('حدث خطأ أثناء التعديل', 'error') }
  }

  async function toggleActive(id: string, current: boolean) {
    setDrivers(prev => prev.map(d => d.id === id ? { ...d, is_active: !current } : d))
    toast(current ? 'تم تعطيل السائق' : 'تم تفعيل السائق')
    const { error } = await supabase.from('users').update({ is_active: !current }).eq('id', id)
    if (error) { toast('حدث خطأ — جاري التحديث', 'error'); loadDrivers() }
  }

  function openEdit(item: any) {
    setForm({ name: item.name, phone: item.phone ?? '', email: item.email ?? '', vehicle_type: item.vehicle_type ?? 'motorcycle', vehicle_number: item.vehicle_number ?? '' })
    setEditItem(item)
  }

  const totalPages = Math.ceil(totalCount / PAGE_SIZE)
  const activeDrivers = drivers.filter(d => d.is_active).length
  const vehicleLabel: Record<string, string> = { motorcycle: 'موتوسيكل', car: 'سيارة', van: 'فان' }

  const columns = [
    { key: 'name', label: 'السائق', render: (item: any) => (
      <div className="flex items-center gap-3">
        <div className="w-8 h-8 rounded-xl bg-gradient-to-br from-orange-400 to-orange-600 flex items-center justify-center text-white text-xs font-bold shadow-premium">{item.name?.[0]}</div>
        <span className="font-medium">{item.name}</span>
      </div>
    )},
    { key: 'phone', label: 'الهاتف' },
    { key: 'email', label: 'البريد', render: (item: any) => item.email ?? <span className="text-gray-300">—</span> },
    { key: 'vehicle_type', label: 'المركبة', render: (item: any) => vehicleLabel[item.vehicle_type] ?? item.vehicle_type ?? '—' },
    { key: 'is_active', label: 'الحالة', render: (item: any) => <Badge variant={item.is_active ? 'success' : 'danger'}>{item.is_active ? 'متاح' : 'غير متاح'}</Badge> },
    { key: 'actions', label: '', render: (item: any) => (
      <div className="flex gap-1">
        <Tooltip content="عرض التفاصيل"><button onClick={() => setDetailItem(item)} className="p-1.5 hover:bg-surface-muted rounded-lg transition-colors"><Eye size={14} className="text-gray-400" /></button></Tooltip>
        <Tooltip content="تعديل"><button onClick={() => openEdit(item)} className="p-1.5 hover:bg-surface-muted rounded-lg transition-colors"><Edit2 size={14} className="text-gray-400" /></button></Tooltip>
        <Tooltip content={item.is_active ? 'تعطيل' : 'تفعيل'}><button onClick={() => toggleActive(item.id, item.is_active)} className="p-1.5 hover:bg-surface-muted rounded-lg transition-colors"><Power size={14} className={item.is_active ? 'text-red-400' : 'text-green-500'} /></button></Tooltip>
      </div>
    )},
  ]

  const inputClass = "w-full p-3 border border-surface-border rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/15 focus:border-primary-500/30 transition-all"

  const formFields = (
    <>
      <div>
        <label className="block text-xs font-medium text-gray-500 mb-1.5">الاسم <span className="text-red-400">*</span></label>
        <input type="text" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} required className={inputClass} />
      </div>
      <div>
        <label className="block text-xs font-medium text-gray-500 mb-1.5">الهاتف <span className="text-red-400">*</span></label>
        <input type="tel" value={form.phone} onChange={e => setForm({ ...form, phone: e.target.value })} required dir="ltr" className={inputClass} />
      </div>
      <div>
        <label className="block text-xs font-medium text-gray-500 mb-1.5">البريد الإلكتروني</label>
        <input type="email" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} dir="ltr" className={inputClass} placeholder="اختياري" />
      </div>
      <div>
        <label className="block text-xs font-medium text-gray-500 mb-1.5">نوع المركبة</label>
        <select value={form.vehicle_type} onChange={e => setForm({ ...form, vehicle_type: e.target.value })} className={inputClass}>
          <option value="motorcycle">موتوسيكل</option><option value="car">سيارة</option><option value="van">فان</option>
        </select>
      </div>
      <div>
        <label className="block text-xs font-medium text-gray-500 mb-1.5">رقم المركبة</label>
        <input type="text" value={form.vehicle_number} onChange={e => setForm({ ...form, vehicle_number: e.target.value })} dir="ltr" className={inputClass} />
      </div>
    </>
  )

  return (
    <PermissionGate permission="drivers.view">
    <div className="space-y-5">
      <motion.div initial={{ opacity: 0, y: -5 }} animate={{ opacity: 1, y: 0 }} className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2"><Truck className="w-5 h-5 text-orange-500" /> إدارة السائقين</h2>
          <p className="text-sm text-gray-400 mt-0.5">{totalCount} سائق</p>
        </div>
        <button onClick={() => { setForm({ name: '', phone: '', email: '', vehicle_type: 'motorcycle', vehicle_number: '' }); setShowAdd(true) }}
          className="flex items-center gap-2 bg-gradient-to-l from-primary-500 to-primary-600 text-white px-4 py-2.5 rounded-xl text-sm font-medium hover:shadow-glow-green transition-all duration-300">
          <Plus size={16} /> سائق جديد
        </button>
      </motion.div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <StatCard label="إجمالي السائقين" value={totalCount} icon={Truck} color="blue" index={0} />
        <StatCard label="متاح" value={activeDrivers} icon={CheckCircle} color="green" index={1} />
        <StatCard label="في مهمة" value={0} icon={Clock} color="orange" index={2} />
        <StatCard label="غير متاح" value={totalCount - activeDrivers} icon={XCircle} color="red" index={3} />
      </div>

      <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.1 }} className="relative max-w-md">
        <Search size={16} className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400" />
        <input type="text" placeholder="بحث بالاسم أو الهاتف..." value={search} onChange={e => { setSearch(e.target.value); setPage(0) }}
          className="w-full pr-10 pl-4 py-2.5 bg-white border border-surface-border/60 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/15 focus:border-primary-500/30 transition-all" />
      </motion.div>

      {loading ? <TableSkeleton rows={5} cols={5} />
        : <DataTable columns={columns} data={drivers} emptyMessage="لا يوجد سائقين" />}

      {totalPages > 1 && (
        <div className="flex items-center justify-center gap-2 mt-4">
          <button onClick={() => setPage(p => Math.max(0, p - 1))} disabled={page === 0}
            className="px-3 py-1.5 text-sm rounded-lg border border-surface-border disabled:opacity-40 hover:bg-surface-muted transition-colors">السابق</button>
          <span className="text-sm text-gray-500">{page + 1} / {totalPages}</span>
          <button onClick={() => setPage(p => Math.min(totalPages - 1, p + 1))} disabled={page >= totalPages - 1}
            className="px-3 py-1.5 text-sm rounded-lg border border-surface-border disabled:opacity-40 hover:bg-surface-muted transition-colors">التالي</button>
        </div>
      )}

      <Modal open={showAdd} onClose={() => setShowAdd(false)} title="سائق جديد">
        <form onSubmit={handleAdd} className="space-y-4">
          {formFields}
          <button type="submit" disabled={saving} className="w-full bg-gradient-to-l from-primary-500 to-primary-600 text-white p-3 rounded-xl font-semibold hover:shadow-glow-green disabled:opacity-50 transition-all">
            {saving ? 'جاري الحفظ...' : 'إضافة السائق'}
          </button>
        </form>
      </Modal>

      <Modal open={!!editItem} onClose={() => setEditItem(null)} title="تعديل السائق">
        <form onSubmit={handleEdit} className="space-y-4">
          {formFields}
          <button type="submit" disabled={saving} className="w-full bg-gradient-to-l from-primary-500 to-primary-600 text-white p-3 rounded-xl font-semibold hover:shadow-glow-green disabled:opacity-50 transition-all">
            {saving ? 'جاري الحفظ...' : 'حفظ التعديلات'}
          </button>
        </form>
      </Modal>

      <Modal open={!!detailItem} onClose={() => setDetailItem(null)} title="تفاصيل السائق">
        {detailItem && (
          <div className="space-y-4">
            <div className="flex items-center gap-4">
              <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-orange-400 to-orange-600 flex items-center justify-center text-white text-xl font-bold shadow-premium-md">{detailItem.name?.[0]}</div>
              <div><h4 className="text-lg font-bold text-gray-800">{detailItem.name}</h4><Badge variant={detailItem.is_active ? 'success' : 'danger'}>{detailItem.is_active ? 'متاح' : 'غير متاح'}</Badge></div>
            </div>
            <div className="grid grid-cols-2 gap-3">
              {[
                { label: 'الهاتف', value: detailItem.phone ?? '—' },
                { label: 'البريد', value: detailItem.email ?? '—' },
                { label: 'المركبة', value: vehicleLabel[detailItem.vehicle_type] ?? '—' },
                { label: 'رقم المركبة', value: detailItem.vehicle_number ?? '—' },
              ].map((item, i) => (
                <div key={i} className="bg-surface-muted/50 rounded-xl p-3">
                  <p className="text-[10px] text-gray-400 mb-0.5">{item.label}</p>
                  <p className="text-sm font-semibold text-gray-800">{item.value}</p>
                </div>
              ))}
            </div>
          </div>
        )}
      </Modal>
    </div>
    </PermissionGate>
  )
}

'use client'

import { useEffect, useState, useMemo } from 'react'
import { supabase } from '@/lib/supabase'
import StatCard from '@/components/ui/StatCard'
import DataTable from '@/components/ui/DataTable'
import Badge from '@/components/ui/Badge'
import { DollarSign, TrendingUp, TrendingDown, CreditCard, Calendar, RotateCcw, Crown, Truck, Download } from 'lucide-react'
import { PageSkeleton } from '@/components/ui/Skeleton'
import Tooltip from '@/components/ui/Tooltip'
import PermissionGate from '@/components/ui/PermissionGate'
import { motion } from 'framer-motion'
import { useToast } from '@/components/ui/Toast'

const today = () => new Date().toISOString().split('T')[0]
const monthStart = () => { const d = new Date(); d.setDate(1); return d.toISOString().split('T')[0] }

type DatePreset = 'all' | 'today' | 'week' | 'month' | 'custom'
type SourceFilter = 'all' | 'orders' | 'subscriptions'

export default function FinancePage() {
  const [stats, setStats] = useState({ revenue: 0, paid: 0, unpaid: 0, ordersCount: 0, subsRevenue: 0, subsCount: 0, deliveryFees: 0 })
  const [rows, setRows] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [payFilter, setPayFilter] = useState('all')
  const [sourceFilter, setSourceFilter] = useState<SourceFilter>('all')
  const [preset, setPreset] = useState<DatePreset>('all')
  const [dateFrom, setDateFrom] = useState('')
  const [dateTo, setDateTo] = useState('')
  const { toast } = useToast()

  useEffect(() => { load() }, [preset, dateFrom, dateTo])

  function getDateRange(): { from: string | null; to: string | null } {
    const now = new Date()
    switch (preset) {
      case 'today':
        return { from: today() + 'T00:00:00', to: today() + 'T23:59:59' }
      case 'week': {
        const w = new Date(now)
        w.setDate(now.getDate() - 7)
        return { from: w.toISOString(), to: now.toISOString() }
      }
      case 'month':
        return { from: monthStart() + 'T00:00:00', to: now.toISOString() }
      case 'custom':
        return { from: dateFrom ? dateFrom + 'T00:00:00' : null, to: dateTo ? dateTo + 'T23:59:59' : null }
      default:
        return { from: null, to: null }
    }
  }

  async function load() {
    const { from, to } = getDateRange()

    // Stats from server-side aggregation (accurate, no row limit)
    const { data: serverStats } = await supabase.rpc('get_finance_stats', {
      date_from: from ?? undefined,
      date_to: to ?? undefined,
    })
    if (serverStats) {
      const s = serverStats as any
      setStats({
        revenue: (Number(s.order_revenue) || 0) + (Number(s.subs_revenue) || 0),
        paid: Number(s.order_paid) || 0,
        unpaid: (Number(s.order_revenue) || 0) - (Number(s.order_paid) || 0),
        ordersCount: Number(s.orders_count) || 0,
        subsRevenue: Number(s.subs_revenue) || 0,
        subsCount: Number(s.subs_count) || 0,
        deliveryFees: Number(s.delivery_fees) || 0,
      })
    }

    // Load rows for the table (paginated display)
    let oQuery = supabase.from('orders')
      .select('id, order_number, status, total, delivery_fee, payment_status, payment_method, subscription_id, created_at, customer:users!orders_customer_id_fkey(name, customer_code)')
      .order('created_at', { ascending: false })
      .limit(200)
    if (from) oQuery = oQuery.gte('created_at', from)
    if (to) oQuery = oQuery.lte('created_at', to)
    const { data: ordersData } = await oQuery

    let sQuery = supabase.from('subscriptions')
      .select('id, status, total_paid, created_at, user:users!subscriptions_user_id_fkey(name, customer_code), plan:plans(name)')
      .not('status', 'in', '("pending","cancelled")')
      .order('created_at', { ascending: false })
      .limit(200)
    if (from) sQuery = sQuery.gte('created_at', from)
    if (to) sQuery = sQuery.lte('created_at', to)
    const { data: subsData } = await sQuery

    const allOrders = ordersData ?? []
    const allSubs = subsData ?? []

    // Merge into unified rows
    const orderRows = allOrders.map((o: any) => ({
      ...o,
      _source: 'order' as const,
      _amount: o.total ?? 0,
      _customerName: o.customer?.name ?? '—',
      _customerCode: o.customer?.customer_code,
      _date: o.created_at,
    }))

    const subRows = allSubs.map((s: any) => ({
      ...s,
      _source: 'subscription' as const,
      _amount: Number(s.total_paid) || 0,
      _customerName: s.user?.name ?? '—',
      _customerCode: s.user?.customer_code,
      _date: s.created_at,
      payment_status: s.status === 'active' ? 'confirmed' : 'pending',
      payment_method: 'subscription',
    }))

    const merged = [...orderRows, ...subRows].sort((a, b) =>
      new Date(b._date).getTime() - new Date(a._date).getTime()
    )

    setRows(merged)
    setLoading(false)
  }

  function resetFilters() {
    setPreset('all')
    setPayFilter('all')
    setSourceFilter('all')
    setDateFrom('')
    setDateTo('')
  }

  const filtered = useMemo(() => {
    let result = rows
    if (sourceFilter !== 'all') result = result.filter(r => r._source === (sourceFilter === 'orders' ? 'order' : 'subscription'))
    if (payFilter !== 'all') result = result.filter(r => r.payment_status === payFilter)
    return result
  }, [rows, sourceFilter, payFilter])

  const paymentLabel: Record<string, string> = { cash: 'كاش', instapay: 'إنستاباي', wallet: 'محفظة', subscription: 'اشتراك' }

  function exportExcel() {
    import('xlsx').then(XLSX => {
      const exportData = filtered.map(r => ({
        'النوع': r._source === 'order' ? 'طلب' : 'اشتراك',
        'المرجع': r._source === 'order' ? r.order_number : r.plan?.name ?? '—',
        'العميل': r._customerName,
        'المبلغ': r._amount?.toFixed(2),
        'طريقة الدفع': paymentLabel[r.payment_method] ?? r.payment_method,
        'حالة الدفع': r.payment_status === 'confirmed' ? 'مدفوع' : r.payment_status === 'refunded' ? 'مسترد' : 'غير مدفوع',
        'التاريخ': new Date(r._date).toLocaleDateString('ar-EG'),
      }))
      const ws = XLSX.utils.json_to_sheet(exportData)
      const wb = XLSX.utils.book_new()
      XLSX.utils.book_append_sheet(wb, ws, 'المالية')
      XLSX.writeFile(wb, `تقرير-مالي-${new Date().toISOString().split('T')[0]}.xlsx`)
      toast('تم تصدير التقرير بنجاح')
    })
  }

  async function markPaid(id: string) {
    const row = rows.find(r => r.id === id)
    const amount = row?._amount ?? 0
    setRows(prev => prev.map(r => r.id === id ? { ...r, payment_status: 'confirmed' } : r))
    setStats(prev => ({ ...prev, paid: prev.paid + amount, unpaid: prev.unpaid - amount }))
    toast('تم تأكيد الدفع بنجاح')
    const { error } = await supabase.from('orders').update({ payment_status: 'confirmed' }).eq('id', id)
    if (error) { toast('حدث خطأ — جاري التحديث', 'error'); load() }
  }

  const columns = [
    { key: 'source', label: 'النوع', render: (item: any) => (
      item._source === 'subscription'
        ? <Badge variant="warning"><span className="flex items-center gap-1">👑 اشتراك</span></Badge>
        : <Badge variant="info">🧺 طلب</Badge>
    )},
    { key: 'ref', label: 'المرجع', render: (item: any) => (
      <span className="font-bold text-navy-800">
        {item._source === 'order' ? item.order_number : item.plan?.name ?? '—'}
      </span>
    )},
    { key: 'customer', label: 'العميل', render: (item: any) => item._customerName },
    { key: 'total', label: 'المبلغ', render: (item: any) => <span className="font-semibold">{item._amount?.toFixed(2)} ج.م</span> },
    { key: 'payment_method', label: 'طريقة الدفع', render: (item: any) => paymentLabel[item.payment_method] ?? item.payment_method },
    { key: 'payment_status', label: 'حالة الدفع', render: (item: any) => (
      <Badge variant={item.payment_status === 'confirmed' ? 'success' : item.payment_status === 'refunded' ? 'danger' : 'warning'}>
        {item.payment_status === 'confirmed' ? 'مدفوع' : item.payment_status === 'refunded' ? 'مسترد' : 'غير مدفوع'}
      </Badge>
    )},
    { key: 'date', label: 'التاريخ', render: (item: any) => (
      <div>
        <span className="text-xs text-gray-600">{new Date(item._date).toLocaleDateString('ar-EG', { year: 'numeric', month: 'short', day: 'numeric' })}</span>
        <p className="text-[10px] text-gray-400">{new Date(item._date).toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' })}</p>
      </div>
    )},
    { key: 'actions', label: '', render: (item: any) => (
      item._source === 'order' && item.payment_status !== 'confirmed' ? (
        <Tooltip content="تأكيد استلام المبلغ">
          <button onClick={() => markPaid(item.id)} className="text-[11px] bg-emerald-50 text-emerald-600 px-3 py-1.5 rounded-lg font-medium hover:bg-emerald-100 transition-colors">
            تأكيد الدفع
          </button>
        </Tooltip>
      ) : null
    )},
  ]

  const presets: { key: DatePreset; label: string }[] = [
    { key: 'all', label: 'الكل' }, { key: 'today', label: 'اليوم' },
    { key: 'week', label: 'آخر أسبوع' }, { key: 'month', label: 'هذا الشهر' },
    { key: 'custom', label: 'مخصص' },
  ]

  const inputClass = 'px-3 py-2 bg-white border border-surface-border/60 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/15 transition-all'

  if (loading) return <PageSkeleton stats={4} tableRows={5} tableCols={5} />

  return (
    <PermissionGate permission="finance.view">
    <div className="space-y-6">
      <motion.div initial={{ opacity: 0, y: -5 }} animate={{ opacity: 1, y: 0 }} className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2"><DollarSign className="w-5 h-5 text-emerald-500" /> المالية</h2>
          <p className="text-sm text-gray-400 mt-0.5">ملخص الإيرادات والمدفوعات</p>
        </div>
        <div className="flex items-center gap-3">
          {(preset !== 'all' || payFilter !== 'all' || sourceFilter !== 'all') && (
            <button onClick={resetFilters} className="flex items-center gap-1.5 text-sm text-gray-500 hover:text-primary-500 transition-colors">
              <RotateCcw size={14} /> إعادة تعيين
            </button>
          )}
          <button onClick={exportExcel} className="flex items-center gap-1.5 bg-emerald-50 text-emerald-600 px-3 py-2 rounded-xl text-xs font-medium hover:bg-emerald-100 transition-colors">
            <Download size={14} /> تصدير Excel
          </button>
        </div>
      </motion.div>

      {/* Date filters */}
      <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.05 }} className="flex flex-wrap items-center gap-3">
        <Calendar size={16} className="text-gray-400" />
        <div className="flex gap-1.5">
          {presets.map(p => (
            <button key={p.key} onClick={() => setPreset(p.key)}
              className={`px-3 py-2 rounded-lg text-[11px] font-medium transition-all ${preset === p.key ? 'bg-navy-900 text-white shadow-premium-md' : 'bg-white text-gray-500 hover:bg-surface-muted border border-surface-border/60'}`}>
              {p.label}
            </button>
          ))}
        </div>
        {preset === 'custom' && (
          <div className="flex items-center gap-2">
            <input type="date" value={dateFrom} onChange={e => setDateFrom(e.target.value)} className={inputClass} />
            <span className="text-gray-400 text-xs">إلى</span>
            <input type="date" value={dateTo} onChange={e => setDateTo(e.target.value)} className={inputClass} />
          </div>
        )}
      </motion.div>

      <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-6 gap-4">
        <StatCard label="إجمالي الإيرادات" value={`${stats.revenue.toLocaleString()} ج.م`} icon={DollarSign} color="green" />
        <StatCard label="المدفوع (طلبات)" value={`${stats.paid.toLocaleString()} ج.م`} icon={TrendingUp} color="blue" />
        <StatCard label="غير مدفوع" value={`${stats.unpaid.toLocaleString()} ج.م`} icon={TrendingDown} color="orange" />
        <StatCard label="رسوم التوصيل" value={`${stats.deliveryFees.toLocaleString()} ج.م`} icon={Truck} color="purple" />
        <StatCard label="إيرادات الاشتراكات" value={`${stats.subsRevenue.toLocaleString()} ج.م`} icon={Crown} color="yellow" />
        <StatCard label="عدد الطلبات" value={stats.ordersCount} icon={CreditCard} color="purple" />
      </div>

      {/* Source + Payment filters */}
      <div className="flex flex-wrap gap-4">
        <div className="flex gap-1.5">
          {([['all', 'الكل'], ['orders', '🧺 الطلبات'], ['subscriptions', '👑 الاشتراكات']] as [SourceFilter, string][]).map(([key, label]) => (
            <button key={key} onClick={() => setSourceFilter(key)}
              className={`px-3 py-2 rounded-lg text-[11px] font-medium transition-all ${sourceFilter === key ? 'bg-navy-900 text-white shadow-premium-md' : 'bg-white text-gray-500 hover:bg-surface-muted border border-surface-border/60'}`}>
              {label}
            </button>
          ))}
        </div>
        <div className="flex gap-1.5">
          {[{ key: 'all', label: 'الكل' }, { key: 'pending', label: 'غير مدفوع' }, { key: 'confirmed', label: 'مدفوع' }].map(f => (
            <button key={f.key} onClick={() => setPayFilter(f.key)}
              className={`px-3 py-2 rounded-lg text-[11px] font-medium transition-all ${payFilter === f.key ? 'bg-navy-900 text-white shadow-premium-md' : 'bg-white text-gray-500 hover:bg-surface-muted border border-surface-border/60'}`}>
              {f.label}
            </button>
          ))}
        </div>
      </div>

      <DataTable columns={columns} data={filtered} emptyMessage="لا توجد معاملات" />
    </div>
    </PermissionGate>
  )
}

'use client'

import { useState, Component, type ReactNode } from 'react'
import Sidebar from '@/components/layout/Sidebar'
import Header from '@/components/layout/Header'
import { ToastProvider } from '@/components/ui/Toast'
import { AuthProvider } from '@/lib/auth-context'
import { ThemeProvider } from '@/lib/theme-context'
import { LanguageProvider } from '@/lib/language-context'
import { motion } from 'framer-motion'
import RealtimeNotifier from '@/components/layout/RealtimeNotifier'

class ErrorBoundary extends Component<{ children: ReactNode }, { hasError: boolean }> {
  state = { hasError: false }
  static getDerivedStateFromError() { return { hasError: true } }
  render() {
    if (this.state.hasError) {
      return (
        <div className="flex flex-col items-center justify-center min-h-[60vh] gap-4">
          <p className="text-6xl">⚠️</p>
          <h2 className="text-xl font-bold text-gray-800">حدث خطأ غير متوقع</h2>
          <p className="text-gray-500">يرجى تحديث الصفحة أو المحاولة لاحقاً</p>
          <button onClick={() => { this.setState({ hasError: false }); window.location.reload() }}
            className="px-6 py-2.5 bg-primary-500 text-white rounded-xl font-medium hover:bg-primary-600 transition-colors">
            تحديث الصفحة
          </button>
        </div>
      )
    }
    return this.props.children
  }
}

export default function DashboardLayout({
  children,
}: {
  children: React.ReactNode
}) {
  const [collapsed, setCollapsed] = useState(false)

  return (
    <ThemeProvider>
      <LanguageProvider>
        <AuthProvider>
          <ToastProvider>
            <RealtimeNotifier />
            <div className="min-h-screen bg-surface">
              <Sidebar collapsed={collapsed} onToggleCollapse={() => setCollapsed(c => !c)} />
              <div className={`${collapsed ? 'mr-[72px]' : 'mr-[260px]'} transition-all duration-300`}>
                <Header />
                <motion.main
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ duration: 0.3, delay: 0.1 }}
                  className="p-6"
                >
                  <ErrorBoundary>
                    {children}
                  </ErrorBoundary>
                </motion.main>
              </div>
            </div>
          </ToastProvider>
        </AuthProvider>
      </LanguageProvider>
    </ThemeProvider>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { supabase } from '@/lib/supabase'
import { motion } from 'framer-motion'
import { Bell, Send, Users, Crown, UserX, Loader2 } from 'lucide-react'
import Badge from '@/components/ui/Badge'
import DataTable from '@/components/ui/DataTable'
import PermissionGate from '@/components/ui/PermissionGate'
import { useToast } from '@/components/ui/Toast'
import { useAuth } from '@/lib/auth-context'

type Target = 'all' | 'subscribers' | 'non_subscribers'

const targetOptions: { key: Target; label: string; icon: typeof Users }[] = [
  { key: 'all', label: 'كل العملاء', icon: Users },
  { key: 'subscribers', label: 'المشتركين فقط', icon: Crown },
  { key: 'non_subscribers', label: 'غير المشتركين', icon: UserX },
]

export default function NotificationsPage() {
  const [title, setTitle] = useState('')
  const [body, setBody] = useState('')
  const [target, setTarget] = useState<Target>('all')
  const [sending, setSending] = useState(false)
  const [history, setHistory] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [recipientCount, setRecipientCount] = useState<number | null>(null)
  const { toast } = useToast()
  const { user: profile } = useAuth()

  useEffect(() => { loadHistory() }, [])
  useEffect(() => { loadRecipientCount() }, [target])

  async function loadHistory() {
    const { data } = await supabase
      .from('broadcast_messages')
      .select('*, sender:users!broadcast_messages_sent_by_fkey(name)')
      .order('created_at', { ascending: false })
      .limit(20)
    setHistory(data ?? [])
    setLoading(false)
  }

  async function loadRecipientCount() {
    let query = supabase
      .from('users')
      .select('id', { count: 'exact', head: true })
      .eq('role', 'customer')
      .not('fcm_token', 'is', null)

    if (target === 'subscribers') {
      const { data: subUsers } = await supabase
        .from('subscriptions')
        .select('user_id')
        .eq('status', 'active')
      const ids = (subUsers ?? []).map(s => s.user_id)
      if (ids.length === 0) { setRecipientCount(0); return }
      query = query.in('id', ids)
    } else if (target === 'non_subscribers') {
      const { data: subUsers } = await supabase
        .from('subscriptions')
        .select('user_id')
        .eq('status', 'active')
      const ids = (subUsers ?? []).map(s => s.user_id)
      if (ids.length > 0) {
        query = (query as any).not('id', 'in', `(${ids.join(',')})`)
      }
    }

    const { count } = await query
    setRecipientCount(count ?? 0)
  }

  async function handleSend() {
    if (!title.trim() || !body.trim()) {
      toast('اكتب العنوان والرسالة', 'error')
      return
    }

    setSending(true)

    // Get target tokens
    let tokenQuery = supabase
      .from('users')
      .select('fcm_token')
      .eq('role', 'customer')
      .not('fcm_token', 'is', null)

    if (target === 'subscribers') {
      const { data: subUsers } = await supabase
        .from('subscriptions')
        .select('user_id')
        .eq('status', 'active')
      const ids = (subUsers ?? []).map(s => s.user_id)
      if (ids.length === 0) {
        toast('لا يوجد مشتركين حالياً', 'error')
        setSending(false)
        return
      }
      tokenQuery = tokenQuery.in('id', ids)
    } else if (target === 'non_subscribers') {
      const { data: subUsers } = await supabase
        .from('subscriptions')
        .select('user_id')
        .eq('status', 'active')
      const ids = (subUsers ?? []).map(s => s.user_id)
      if (ids.length > 0) {
        tokenQuery = (tokenQuery as any).not('id', 'in', `(${ids.join(',')})`)
      }
    }

    const { data: users } = await tokenQuery
    const tokens = (users ?? []).map(u => u.fcm_token).filter(Boolean)

    if (tokens.length === 0) {
      toast('لا يوجد عملاء لديهم إشعارات مفعلة', 'error')
      setSending(false)
      return
    }

    // Send in batches of 100
    const batches = []
    for (let i = 0; i < tokens.length; i += 100) {
      batches.push(tokens.slice(i, i + 100))
    }

    let successCount = 0
    for (const batch of batches) {
      try {
        const messages = batch.map(token => ({
          to: token,
          title: title.trim(),
          body: body.trim(),
          sound: 'default',
          data: { type: 'broadcast' },
        }))
        const res = await fetch('https://exp.host/--/api/v2/push/send', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(messages),
        })
        if (res.ok) successCount += batch.length
      } catch {}
    }

    // Log to database
    await supabase.from('broadcast_messages').insert({
      title: title.trim(),
      body: body.trim(),
      target,
      sent_by: profile?.id,
      recipients_count: successCount,
    })

    toast(`تم إرسال الإشعار لـ ${successCount} عميل`)
    setTitle('')
    setBody('')
    setSending(false)
    loadHistory()
  }

  const targetLabel: Record<string, string> = {
    all: 'كل العملاء',
    subscribers: 'المشتركين',
    non_subscribers: 'غير المشتركين',
  }

  const columns = [
    {
      key: 'title',
      label: 'العنوان',
      render: (item: any) => (
        <div>
          <p className="font-semibold text-gray-800">{item.title}</p>
          <p className="text-xs text-gray-400 mt-0.5 line-clamp-1">{item.body}</p>
        </div>
      ),
    },
    {
      key: 'target',
      label: 'الفئة',
      render: (item: any) => (
        <Badge variant={item.target === 'all' ? 'info' : item.target === 'subscribers' ? 'warning' : 'neutral'}>
          {targetLabel[item.target] ?? item.target}
        </Badge>
      ),
    },
    {
      key: 'recipients_count',
      label: 'عدد المستلمين',
      render: (item: any) => <span className="font-semibold">{item.recipients_count}</span>,
    },
    {
      key: 'sender',
      label: 'المرسل',
      render: (item: any) => <span className="text-gray-600">{item.sender?.name ?? '—'}</span>,
    },
    {
      key: 'created_at',
      label: 'التاريخ',
      render: (item: any) => (
        <div>
          <span className="text-xs text-gray-600">
            {new Date(item.created_at).toLocaleDateString('ar-EG', { year: 'numeric', month: 'short', day: 'numeric' })}
          </span>
          <p className="text-[10px] text-gray-400">
            {new Date(item.created_at).toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' })}
          </p>
        </div>
      ),
    },
  ]

  const inputClass = 'w-full px-4 py-3 bg-white border border-surface-border/60 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/20 transition-all text-right'

  return (
    <PermissionGate permission="customers.view">
      <div className="space-y-6">
        <motion.div initial={{ opacity: 0, y: -5 }} animate={{ opacity: 1, y: 0 }}>
          <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
            <Bell className="w-5 h-5 text-primary-500" />
            الإشعارات الجماعية
          </h2>
          <p className="text-sm text-gray-400 mt-0.5">أرسل إشعارات لعملائك</p>
        </motion.div>

        {/* Compose */}
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="bg-white rounded-2xl border border-surface-border/60 p-6 space-y-5"
        >
          <h3 className="font-semibold text-gray-700 flex items-center gap-2">
            <Send size={16} className="text-primary-500" />
            إرسال إشعار جديد
          </h3>

          {/* Target */}
          <div>
            <label className="text-xs font-medium text-gray-500 mb-2 block">الفئة المستهدفة</label>
            <div className="flex gap-2">
              {targetOptions.map(opt => {
                const Icon = opt.icon
                return (
                  <button
                    key={opt.key}
                    onClick={() => setTarget(opt.key)}
                    className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-[12px] font-medium transition-all ${
                      target === opt.key
                        ? 'bg-navy-900 text-white shadow-premium-md'
                        : 'bg-white text-gray-500 hover:bg-surface-muted border border-surface-border/60'
                    }`}
                  >
                    <Icon size={14} />
                    {opt.label}
                  </button>
                )
              })}
              {recipientCount !== null && (
                <span className="flex items-center text-xs text-gray-400 mr-2">
                  ({recipientCount} مستلم)
                </span>
              )}
            </div>
          </div>

          {/* Title */}
          <div>
            <label className="text-xs font-medium text-gray-500 mb-2 block">عنوان الإشعار</label>
            <input
              type="text"
              value={title}
              onChange={e => setTitle(e.target.value)}
              placeholder="مثال: عرض خاص لعملائنا"
              className={inputClass}
              maxLength={100}
            />
          </div>

          {/* Body */}
          <div>
            <label className="text-xs font-medium text-gray-500 mb-2 block">نص الرسالة</label>
            <textarea
              value={body}
              onChange={e => setBody(e.target.value)}
              placeholder="اكتب الرسالة هنا..."
              className={`${inputClass} min-h-[100px] resize-none`}
              maxLength={500}
            />
            <p className="text-[10px] text-gray-400 mt-1 text-left">{body.length}/500</p>
          </div>

          {/* Send */}
          <button
            onClick={handleSend}
            disabled={sending || !title.trim() || !body.trim()}
            className="flex items-center justify-center gap-2 w-full bg-primary-500 hover:bg-primary-600 disabled:opacity-50 disabled:cursor-not-allowed text-white font-semibold py-3 px-6 rounded-xl transition-all shadow-premium-md"
          >
            {sending ? (
              <>
                <Loader2 size={16} className="animate-spin" />
                جاري الإرسال...
              </>
            ) : (
              <>
                <Send size={16} />
                إرسال الإشعار
              </>
            )}
          </button>
        </motion.div>

        {/* History */}
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
        >
          <h3 className="text-lg font-semibold text-gray-800 mb-4">سجل الإشعارات المرسلة</h3>
          {loading ? (
            <div className="flex items-center justify-center h-32">
              <div className="w-8 h-8 border-4 border-primary-500 border-t-transparent rounded-full animate-spin" />
            </div>
          ) : (
            <DataTable columns={columns} data={history} emptyMessage="لا توجد إشعارات مرسلة بعد" />
          )}
        </motion.div>
      </div>
    </PermissionGate>
  )
}

'use client'

import { useEffect, useState, useMemo, useRef, useCallback } from 'react'
import { motion } from 'framer-motion'
import { supabase } from '@/lib/supabase'
import DataTable from '@/components/ui/DataTable'
import Badge from '@/components/ui/Badge'
import Modal from '@/components/ui/Modal'
import {
  ClipboardList,
  Plus,
  Search,
  Eye,
  ArrowRight,
} from 'lucide-react'
import { PageSkeleton } from '@/components/ui/Skeleton'
import { useToast } from '@/components/ui/Toast'
import Tooltip from '@/components/ui/Tooltip'
import PermissionGate from '@/components/ui/PermissionGate'
import { isValidEgyptianPhone } from '@/lib/utils'
import { ORDER_STATUS_LABELS, SERVICE_TYPE_LABELS } from '@cleano/shared-types'
import type { OrderStatus, ServiceType } from '@cleano/shared-types'

const statusVariant: Record<string, 'success' | 'warning' | 'danger' | 'info' | 'neutral' | 'purple'> = {
  pending: 'warning', assigned: 'info', picked_up: 'purple', processing: 'info',
  ready: 'success', delivering: 'purple', delivered: 'success', cancelled: 'danger', refunded: 'neutral',
}

const statusFlow: Record<string, string> = {
  pending: 'assigned', assigned: 'picked_up', picked_up: 'processing',
  processing: 'ready', ready: 'delivering', delivering: 'delivered',
}

const walkinStatusFlow: Record<string, string> = {
  pending: 'processing', assigned: 'processing', picked_up: 'processing',
  processing: 'ready', ready: 'delivered',
}

export default function OrdersPage() {
  const [orders, setOrders] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [search, setSearch] = useState('')
  const [statusFilter, setStatusFilter] = useState('all')
  const [detail, setDetail] = useState<any>(null)
  const [showAdd, setShowAdd] = useState(false)
  const [drivers, setDrivers] = useState<any[]>([])
  const [customers, setCustomers] = useState<any[]>([])
  const [saving, setSaving] = useState(false)
  const [form, setForm] = useState({ customer_id: '', service_type: 'wash', items_count: 1, notes: '', total: '' as any, order_type: 'delivery' as 'delivery' | 'walkin', walkin_name: '', walkin_phone: '' })
  const [messages, setMessages] = useState<any[]>([])
  const [msgsLoading, setMsgsLoading] = useState(false)
  const [deliveryFeeSetting, setDeliveryFeeSetting] = useState(0)
  const [avgPrices, setAvgPrices] = useState<Record<string, number>>({})
  const [page, setPage] = useState(0)
  const [totalCount, setTotalCount] = useState(0)
  const { toast } = useToast()
  const PAGE_SIZE = 20

  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const debouncedLoadOrders = useCallback(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current)
    debounceRef.current = setTimeout(() => loadOrders(), 2000)
  }, [])

  useEffect(() => {
    loadOrders()
    loadDriversCustomers()
    supabase.from('settings').select('value').eq('key', 'delivery_fee').single().then(({ data }) => {
      if (data) setDeliveryFeeSetting(Number(data.value) || 0)
    })
    supabase.from('prices').select('service_type, price').eq('is_active', true).then(({ data }) => {
      if (data) {
        const grouped: Record<string, number[]> = {}
        data.forEach((p: any) => { (grouped[p.service_type] ??= []).push(Number(p.price)) })
        const avgs: Record<string, number> = {}
        for (const [k, v] of Object.entries(grouped)) { avgs[k] = Math.round(v.reduce((a, b) => a + b, 0) / v.length) }
        setAvgPrices(avgs)
      }
    })
    const ch = supabase.channel('orders-rt')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, () => debouncedLoadOrders())
      .subscribe()
    return () => { supabase.removeChannel(ch); if (debounceRef.current) clearTimeout(debounceRef.current) }
  }, [])

  useEffect(() => { loadOrders() }, [page, statusFilter])

  async function loadOrders() {
    let query = supabase.from('orders')
      .select('id, order_number, status, service_type, items_count, total, delivery_fee, notes, payment_status, payment_method, subscription_id, customer_id, driver_id, created_at, customer:users!orders_customer_id_fkey(name, phone, customer_code), driver:users!orders_driver_id_fkey(name, phone), subscription:subscriptions(items_used, items_limit)', { count: 'exact' })
      .order('created_at', { ascending: false })

    if (statusFilter !== 'all') query = query.eq('status', statusFilter)

    query = query.range(page * PAGE_SIZE, (page + 1) * PAGE_SIZE - 1)

    const { data, count } = await query
    setOrders(data ?? [])
    setTotalCount(count ?? 0)
    setLoading(false)
  }

  async function loadDriversCustomers() {
    const [d, c] = await Promise.all([
      supabase.from('users').select('id, name, phone').eq('role', 'driver').eq('is_active', true),
      supabase.from('users').select('id, name, phone, customer_code').eq('role', 'customer'),
    ])
    setDrivers(d.data ?? [])
    setCustomers(c.data ?? [])
  }

  async function assignDriver(orderId: string, driverId: string) {
    const order = orders.find(o => o.id === orderId)
    if (order?.notes?.includes('[من المحل]')) { toast('طلب من المحل لا يحتاج سائق', 'error'); return }
    const driverInfo = drivers.find(d => d.id === driverId)
    setOrders(prev => prev.map(o => o.id === orderId ? { ...o, driver_id: driverId, status: 'assigned', driver: driverInfo } : o))
    setDetail((prev: any) => prev?.id === orderId ? { ...prev, driver_id: driverId, status: 'assigned', driver: driverInfo ?? prev.driver } : prev)
    toast('تم تعيين السائق')
    const { error } = await supabase.from('orders').update({ driver_id: driverId, status: 'assigned' }).eq('id', orderId)
    if (error) { toast('حدث خطأ — جاري التحديث', 'error'); loadOrders(); return }
    await supabase.from('order_status_history').insert({ order_id: orderId, status: 'assigned', changed_by: driverId })
  }

  async function advanceStatus(order: any) {
    const isWalkin = order.notes?.includes('[من المحل]')
    const flow = isWalkin ? walkinStatusFlow : statusFlow
    const next = flow[order.status]
    if (!next) return
    setOrders(prev => prev.map(o => o.id === order.id ? { ...o, status: next } : o))
    setDetail((prev: any) => prev ? { ...prev, status: next } : null)
    toast(`تم تحديث الحالة إلى: ${ORDER_STATUS_LABELS[next as OrderStatus]}`)
    const { error } = await supabase.from('orders').update({ status: next }).eq('id', order.id)
    if (error) { toast('حدث خطأ — جاري التحديث', 'error'); loadOrders(); return }
    await supabase.from('order_status_history').insert({ order_id: order.id, status: next })
  }

  async function loadMessages(orderId: string) {
    setMsgsLoading(true)
    const { data } = await supabase.from('messages')
      .select('*, sender:users!messages_sender_id_fkey(name, role)')
      .eq('order_id', orderId)
      .order('created_at', { ascending: true })
    setMessages(data ?? [])
    setMsgsLoading(false)
  }

  function openDetail(order: any) {
    setDetail(order)
    loadMessages(order.id)
  }

  async function cancelOrder(id: string) {
    const order = orders.find(o => o.id === id)
    setOrders(prev => prev.map(o => o.id === id ? { ...o, status: 'cancelled' } : o))
    setDetail(null)
    toast('تم إلغاء الطلب', 'warning')
    const { error } = await supabase.from('orders').update({ status: 'cancelled' }).eq('id', id)
    if (error) { toast('حدث خطأ — جاري التحديث', 'error'); loadOrders(); return }
    await supabase.from('order_status_history').insert({ order_id: id, status: 'cancelled' })
    if (order?.subscription_id && order.items_count) {
      const { data: sub } = await supabase.from('subscriptions').select('items_used').eq('id', order.subscription_id).single()
      if (sub) {
        const newUsed = Math.max(0, (sub.items_used ?? 0) - order.items_count)
        await supabase.from('subscriptions').update({ items_used: newUsed }).eq('id', order.subscription_id)
      }
    }
  }

  async function handleAddOrder(e: React.FormEvent) {
    e.preventDefault()
    const isWalkin = form.order_type === 'walkin'
    if (isWalkin && !isValidEgyptianPhone(form.walkin_phone)) { toast('رقم الموبايل غير صحيح — يجب أن يبدأ بـ 01 ويكون 11 رقم', 'error'); return }
    setSaving(true)
    const total = form.total || 0

    let customerId = form.customer_id

    if (isWalkin) {
      const { data: existing } = await supabase.from('users').select('id').eq('phone', form.walkin_phone).eq('role', 'customer').single()
      if (existing) {
        customerId = existing.id
      } else {
        const { data: newId, error: rpcErr } = await supabase.rpc('create_walkin_customer', { p_name: form.walkin_name, p_phone: form.walkin_phone })
        if (rpcErr || !newId) { setSaving(false); toast('خطأ في إنشاء العميل', 'error'); return }
        customerId = newId
      }
    }

    const { error } = await supabase.from('orders').insert({
      customer_id: customerId, service_type: form.service_type,
      items_count: form.items_count, notes: isWalkin ? `[من المحل] ${form.walkin_name} - ${form.walkin_phone}${form.notes ? '\n' + form.notes : ''}` : (form.notes || null),
      status: isWalkin ? 'processing' : 'pending',
      payment_status: 'pending', payment_method: 'cash',
      subtotal: total, delivery_fee: isWalkin ? 0 : deliveryFeeSetting, total: isWalkin ? total : total + deliveryFeeSetting, delivery_location: {},
    })
    setSaving(false)
    if (!error) {
      setShowAdd(false)
      setForm({ customer_id: '', service_type: 'wash', items_count: 1, notes: '', total: 0, order_type: 'delivery', walkin_name: '', walkin_phone: '' })
      loadOrders(); toast(isWalkin ? 'تم إضافة طلب من المحل' : 'تم إضافة الطلب')
    } else { console.error('Order insert error:', error); toast('حدث خطأ', 'error') }
  }

  const allStatuses = ['all', 'pending', 'assigned', 'picked_up', 'processing', 'ready', 'delivering', 'delivered', 'cancelled']
  const totalPages = Math.ceil(totalCount / PAGE_SIZE)
  const filtered = useMemo(() => orders.filter(o => {
    if (!search) return true
    const s = search.toLowerCase()
    return o.order_number?.toLowerCase().includes(s) || o.customer?.name?.toLowerCase().includes(s)
  }), [orders, search])

  const columns = [
    { key: 'order_number', label: 'رقم الطلب', render: (item: any) => <span className="font-semibold text-navy-800">{item.order_number}</span> },
    { key: 'customer', label: 'العميل', render: (item: any) => (
      <div>
        <p className="font-medium text-gray-800">{item.customer?.name ?? '—'}</p>
        <p className="text-[10px] text-gray-400">{item.customer?.customer_code}</p>
      </div>
    )},
    { key: 'type', label: 'النوع', render: (item: any) => {
      if (item.notes?.includes('[من المحل]')) return <Badge variant="warning">من المحل</Badge>
      if (item.subscription_id) return <Badge variant="info">باقة</Badge>
      return <Badge variant="neutral">عادي</Badge>
    }},
    { key: 'service_type', label: 'الخدمة', render: (item: any) => <span className="text-gray-600 text-xs">{SERVICE_TYPE_LABELS[item.service_type as ServiceType] ?? item.service_type}</span> },
    { key: 'items_count', label: 'القطع', render: (item: any) => (
      <div>
        <span className="text-gray-600">{item.items_count}</span>
        {item.subscription && (
          <p className="text-[10px] text-primary-500 font-medium">{item.subscription.items_used} من {item.subscription.items_limit}</p>
        )}
      </div>
    )},
    { key: 'total', label: 'المبلغ', render: (item: any) => <span className="font-semibold text-gray-800">{item.total ? `${item.total.toFixed(2)} ج.م` : '—'}</span> },
    { key: 'driver', label: 'السائق', render: (item: any) => item.notes?.includes('[من المحل]') ? <span className="text-gray-300">—</span> : (item.driver?.name ?? <span className="text-gray-300">—</span>) },
    { key: 'status', label: 'الحالة', render: (item: any) => <Badge variant={statusVariant[item.status] ?? 'neutral'}>{ORDER_STATUS_LABELS[item.status as OrderStatus] ?? item.status}</Badge> },
    { key: 'actions', label: '', render: (item: any) => (
      <Tooltip content="عرض التفاصيل">
        <button onClick={() => openDetail(item)} className="p-1.5 hover:bg-surface-muted rounded-lg transition-colors">
          <Eye size={15} className="text-gray-400 hover:text-gray-600" />
        </button>
      </Tooltip>
    )},
  ]

  const inputClass = "w-full p-3 border border-surface-border rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/15 focus:border-primary-500/30 transition-all"

  return (
    <PermissionGate permission="orders.view">
    <div className="space-y-5">
      <motion.div initial={{ opacity: 0, y: -5 }} animate={{ opacity: 1, y: 0 }} className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
            <ClipboardList className="w-5 h-5 text-primary-500" /> إدارة الطلبات
          </h2>
          <p className="text-sm text-gray-400 mt-0.5">{totalCount} طلب</p>
        </div>
        <button onClick={() => setShowAdd(true)}
          className="flex items-center gap-2 bg-gradient-to-l from-primary-500 to-primary-600 text-white px-4 py-2.5 rounded-xl text-sm font-medium hover:shadow-glow-green transition-all duration-300">
          <Plus size={16} /> طلب جديد
        </button>
      </motion.div>

      <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.1 }} className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search size={16} className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400" />
          <input type="text" placeholder="بحث برقم الطلب أو اسم العميل..." value={search} onChange={e => setSearch(e.target.value)}
            className="w-full pr-10 pl-4 py-2.5 bg-white border border-surface-border/60 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/15 focus:border-primary-500/30 transition-all" />
        </div>
        <div className="flex gap-1.5 overflow-x-auto pb-1">
          {allStatuses.map(s => (
            <button key={s} onClick={() => { setStatusFilter(s); setPage(0) }}
              className={`px-3 py-2 rounded-lg text-[11px] font-medium transition-all whitespace-nowrap ${statusFilter === s ? 'bg-navy-900 text-white shadow-premium-md' : 'bg-white text-gray-500 hover:bg-surface-muted border border-surface-border/60'}`}>
              {s === 'all' ? 'الكل' : ORDER_STATUS_LABELS[s as OrderStatus] ?? s}
            </button>
          ))}
        </div>
      </motion.div>

      {loading ? (
        <PageSkeleton stats={0} tableRows={6} tableCols={6} />
      ) : (
        <>
          <DataTable columns={columns} data={filtered} emptyMessage="لا توجد طلبات" pageSize={PAGE_SIZE} />
          {totalPages > 1 && (
            <div className="flex items-center justify-between mt-3">
              <span className="text-xs text-gray-400">صفحة {page + 1} من {totalPages}</span>
              <div className="flex items-center gap-1">
                <button onClick={() => setPage(p => p - 1)} disabled={page === 0}
                  className="w-8 h-8 flex items-center justify-center rounded-lg hover:bg-surface-muted disabled:opacity-30 disabled:cursor-not-allowed transition-colors">
                  <span className="text-gray-600 text-sm">›</span>
                </button>
                {Array.from({ length: Math.min(totalPages, 5) }, (_, i) => {
                  const pageNum = totalPages <= 5 ? i : page < 3 ? i : page > totalPages - 4 ? totalPages - 5 + i : page - 2 + i
                  return (
                    <button key={pageNum} onClick={() => setPage(pageNum)}
                      className={`w-8 h-8 rounded-lg text-xs font-medium transition-all ${page === pageNum ? 'bg-navy-900 text-white shadow-premium-md' : 'text-gray-500 hover:bg-surface-muted'}`}>
                      {pageNum + 1}
                    </button>
                  )
                })}
                <button onClick={() => setPage(p => p + 1)} disabled={page >= totalPages - 1}
                  className="w-8 h-8 flex items-center justify-center rounded-lg hover:bg-surface-muted disabled:opacity-30 disabled:cursor-not-allowed transition-colors">
                  <span className="text-gray-600 text-sm">‹</span>
                </button>
              </div>
            </div>
          )}
        </>
      )}

      <Modal open={!!detail} onClose={() => setDetail(null)} title={`تفاصيل الطلب ${detail?.order_number ?? ''}`}>
        {detail && (
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-3">
              {[
                { label: 'العميل', value: <div><p>{detail.customer?.name}</p>{detail.customer?.phone && <p className="text-[11px] text-gray-400 font-normal mt-0.5" dir="ltr">{detail.customer.phone}</p>}</div> },
                { label: 'الحالة', value: <Badge variant={statusVariant[detail.status]}>{ORDER_STATUS_LABELS[detail.status as OrderStatus]}</Badge> },
                { label: 'المبلغ', value: `${detail.total?.toFixed(2) ?? '—'} ج.م` },
                { label: 'القطع', value: `${detail.items_count} قطعة` },
              ].map((item, i) => (
                <div key={i} className="bg-surface-muted/50 rounded-xl p-3">
                  <p className="text-[10px] text-gray-400 mb-0.5">{item.label}</p>
                  <div className="text-sm font-semibold text-gray-800">{item.value}</div>
                </div>
              ))}
            </div>

            {detail.notes && (
              <div className="bg-amber-50/50 rounded-xl p-3 border border-amber-100">
                <p className="text-[10px] text-amber-600 mb-0.5">ملاحظات</p>
                <p className="text-sm text-amber-800">{detail.notes}</p>
              </div>
            )}

            {['pending', 'assigned'].includes(detail.status) && !detail.notes?.includes('[من المحل]') && (
              <div>
                <p className="text-xs font-medium text-gray-500 mb-1.5">{detail.driver_id ? 'تغيير السائق' : 'تعيين سائق'}</p>
                <select value={detail.driver_id ?? ''} onChange={e => { if (e.target.value && e.target.value !== detail.driver_id) assignDriver(detail.id, e.target.value) }} className={inputClass}>
                  {!detail.driver_id && <option value="">اختر سائق...</option>}
                  {drivers.map(d => <option key={d.id} value={d.id}>{d.name} — {d.phone}</option>)}
                </select>
              </div>
            )}

            {detail.driver && !detail.notes?.includes('[من المحل]') && (
              <div className="bg-blue-50/50 rounded-xl p-3 border border-blue-100">
                <p className="text-[10px] text-blue-600 mb-0.5">السائق الحالي</p>
                <p className="text-sm font-semibold text-blue-800">{detail.driver.name} — {detail.driver.phone}</p>
              </div>
            )}

            <div className="bg-surface-muted/30 rounded-xl p-3 border border-navy-100">
              <p className="text-[10px] text-gray-400 mb-2 font-medium">المحادثة</p>
              {msgsLoading ? (
                <p className="text-xs text-gray-400 text-center py-4">جاري التحميل...</p>
              ) : messages.length === 0 ? (
                <p className="text-xs text-gray-400 text-center py-4">لا توجد رسائل</p>
              ) : (
                <div className="space-y-2 max-h-60 overflow-y-auto">
                  {messages.map(msg => (
                    <div key={msg.id} className={`flex flex-col ${msg.sender?.role === 'driver' ? 'items-start' : 'items-end'}`}>
                      <p className="text-[10px] text-gray-400 mb-0.5">{msg.sender?.name} — {msg.sender?.role === 'driver' ? 'سائق' : 'عميل'}</p>
                      <div className={`px-3 py-2 rounded-xl max-w-[80%] text-sm ${msg.sender?.role === 'driver' ? 'bg-blue-50 text-blue-800' : 'bg-green-50 text-green-800'}`}>
                        {msg.body}
                      </div>
                      <p className="text-[9px] text-gray-300 mt-0.5">{new Date(msg.created_at).toLocaleString('ar-EG', { hour: '2-digit', minute: '2-digit', day: 'numeric', month: 'short' })}</p>
                    </div>
                  ))}
                </div>
              )}
            </div>

            <div className="flex gap-2 pt-2">
              {(() => {
                const isWalkin = detail.notes?.includes('[من المحل]')
                const flow = isWalkin ? walkinStatusFlow : statusFlow
                const next = flow[detail.status]
                return next ? (
                  <button onClick={() => advanceStatus(detail)}
                    className="flex-1 flex items-center justify-center gap-2 bg-gradient-to-l from-primary-500 to-primary-600 text-white p-3 rounded-xl font-semibold text-sm hover:shadow-glow-green transition-all">
                    <ArrowRight size={16} /> {ORDER_STATUS_LABELS[next as OrderStatus]}
                  </button>
                ) : null
              })()}
              {!['delivered', 'cancelled', 'refunded'].includes(detail.status) && (
                <button onClick={() => cancelOrder(detail.id)}
                  className="px-4 py-3 border border-red-200 text-red-500 rounded-xl text-sm font-medium hover:bg-red-50 transition-colors">
                  إلغاء
                </button>
              )}
