            <select value={form.customer_id} onChange={e => setForm({ ...form, customer_id: e.target.value })} required className={inputClass}>
              <option value="">اختر عميل...</option>
              {customers.map(c => <option key={c.id} value={c.id}>{c.name} ({c.customer_code})</option>)}
            </select>
          </div>
          ) : (
          <>
            <div>
              <label className="block text-xs font-medium text-gray-500 mb-1.5">اسم العميل <span className="text-red-400">*</span></label>
              <input type="text" value={form.walkin_name} onChange={e => setForm({ ...form, walkin_name: e.target.value })} required className={inputClass} placeholder="اسم العميل" />
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-500 mb-1.5">رقم الموبايل <span className="text-red-400">*</span></label>
              <input type="tel" value={form.walkin_phone} onChange={e => setForm({ ...form, walkin_phone: e.target.value })} required className={inputClass} placeholder="01xxxxxxxxx" dir="ltr" />
            </div>
          </>
          )}
          <div>
            <label className="block text-xs font-medium text-gray-500 mb-1.5">الخدمة <span className="text-red-400">*</span></label>
            <select value={form.service_type} onChange={e => {
              const st = e.target.value
              const avg = avgPrices[st] ?? 0
              setForm({ ...form, service_type: st, total: avg ? avg * form.items_count : form.total })
            }} required className={inputClass}>
              <option value="wash">غسيل</option><option value="iron">كوي</option>
              <option value="wash_iron">غسيل وكوي</option><option value="dry_clean">تنظيف جاف</option>
            </select>
          </div>
          <div>
            <label className="block text-xs font-medium text-gray-500 mb-1.5">عدد القطع <span className="text-red-400">*</span></label>
            <input type="number" min={1} value={form.items_count} onChange={e => {
              const count = +e.target.value || 1
              const avg = avgPrices[form.service_type] ?? 0
              setForm({ ...form, items_count: count, total: avg ? avg * count : form.total })
            }} required className={inputClass} />
          </div>
          <div>
            <label className="block text-xs font-medium text-gray-500 mb-1.5">المبلغ (ج.م) <span className="text-red-400">*</span></label>
            <input type="number" min={0} step="0.01" value={form.total} onChange={e => setForm({ ...form, total: e.target.value === '' ? '' as any : +e.target.value })} required className={inputClass} placeholder="0.00" />
            {avgPrices[form.service_type] && <p className="text-[10px] text-gray-400 mt-1">محسوب تلقائي (متوسط {avgPrices[form.service_type]} ج.م × {form.items_count} قطعة) — يمكنك تعديله</p>}
          </div>
          <div>
            <label className="block text-xs font-medium text-gray-500 mb-1.5">ملاحظات</label>
            <textarea value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} rows={2} className={inputClass + ' resize-none'} placeholder="اختياري" />
          </div>
          <button type="submit" disabled={saving}
            className="w-full bg-gradient-to-l from-primary-500 to-primary-600 text-white p-3 rounded-xl font-semibold hover:shadow-glow-green disabled:opacity-50 transition-all">
            {saving ? 'جاري الحفظ...' : 'إضافة الطلب'}
          </button>
        </form>
      </Modal>
    </div>
    </PermissionGate>
  )
}

'use client'

import { useEffect, useState, useRef, useCallback } from 'react'
import { motion } from 'framer-motion'
import { supabase } from '@/lib/supabase'
import StatCard from '@/components/ui/StatCard'
import DataTable from '@/components/ui/DataTable'
import Badge from '@/components/ui/Badge'
import {
  DollarSign,
  ClipboardList,
  Users,
  Truck,
  TrendingUp,
  ShoppingBag,
  ArrowUpLeft,
  Sparkles,
  Activity,
} from 'lucide-react'
import { ORDER_STATUS_LABELS } from '@cleano/shared-types'
import type { Order } from '@cleano/shared-types'

const statusBadge = (status: string) => {
  const map: Record<string, 'success' | 'warning' | 'danger' | 'info' | 'neutral' | 'purple'> = {
    pending: 'warning',
    assigned: 'info',
    picked_up: 'purple',
    processing: 'info',
    ready: 'success',
    delivering: 'purple',
    delivered: 'success',
    cancelled: 'danger',
    refunded: 'neutral',
  }
  return (
    <Badge variant={map[status] ?? 'neutral'}>
      {ORDER_STATUS_LABELS[status as keyof typeof ORDER_STATUS_LABELS] ?? status}
    </Badge>
  )
}

function SkeletonLoader() {
  return (
    <div className="space-y-6 animate-fade-in">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4">
        {Array.from({ length: 6 }).map((_, i) => (
          <div key={i} className="bg-white rounded-2xl p-5 border border-surface-border/60">
            <div className="skeleton w-10 h-10 rounded-xl mb-4" />
            <div className="skeleton w-20 h-7 mb-2" />
            <div className="skeleton w-16 h-3" />
          </div>
        ))}
      </div>
      <div className="bg-white rounded-2xl p-6 border border-surface-border/60">
        <div className="skeleton w-32 h-5 mb-6" />
        {Array.from({ length: 4 }).map((_, i) => (
          <div key={i} className="flex gap-4 mb-4">
            <div className="skeleton w-20 h-4 flex-shrink-0" />
            <div className="skeleton w-28 h-4 flex-shrink-0" />
            <div className="skeleton flex-1 h-4" />
            <div className="skeleton w-16 h-4 flex-shrink-0" />
          </div>
        ))}
      </div>
    </div>
  )
}

export default function DashboardPage() {
  const [stats, setStats] = useState({
    totalRevenue: 0,
    totalOrders: 0,
    totalCustomers: 0,
    totalDrivers: 0,
    activeOrders: 0,
    deliveredToday: 0,
  })
  const [recentOrders, setRecentOrders] = useState<any[]>([])
  const [loading, setLoading] = useState(true)

  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const debouncedLoad = useCallback(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current)
    debounceRef.current = setTimeout(() => loadDashboard(), 3000)
  }, [])

  useEffect(() => {
    loadDashboard()
    const channel = supabase.channel('dashboard-realtime')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, () => debouncedLoad())
      .on('postgres_changes', { event: '*', schema: 'public', table: 'users' }, () => debouncedLoad())
      .subscribe()
    return () => { supabase.removeChannel(channel); if (debounceRef.current) clearTimeout(debounceRef.current) }
  }, [])

  async function loadDashboard() {
    const [orders, customers, drivers, recent, subs] = await Promise.all([
      supabase.from('orders').select('id, total, status', { count: 'exact' }),
      supabase.from('users').select('id', { count: 'exact', head: true }).eq('role', 'customer'),
      supabase.from('users').select('id', { count: 'exact', head: true }).eq('role', 'driver'),
      supabase.from('orders').select('*, customer:users!orders_customer_id_fkey(name, customer_code)').order('created_at', { ascending: false }).limit(7),
      supabase.from('subscriptions').select('total_paid, status').not('status', 'in', '("pending","cancelled")'),
    ])

    const allOrders = orders.data ?? []
    const activeOrders = allOrders.filter(o => !['cancelled', 'refunded'].includes(o.status))
    const ordersRevenue = activeOrders.reduce((sum, o) => sum + (o.total ?? 0), 0)
    const subsRevenue = (subs.data ?? []).reduce((sum: number, s: any) => sum + (Number(s.total_paid) || 0), 0)
    const active = allOrders.filter(o => !['delivered', 'cancelled', 'refunded'].includes(o.status)).length

    setStats({
      totalRevenue: ordersRevenue + subsRevenue,
      totalOrders: orders.count ?? 0,
      totalCustomers: customers.count ?? 0,
      totalDrivers: drivers.count ?? 0,
      activeOrders: active,
      deliveredToday: allOrders.filter(o => o.status === 'delivered').length,
    })

    setRecentOrders(recent.data ?? [])
    setLoading(false)
  }

  const orderColumns = [
    {
      key: 'order_number',
      label: 'رقم الطلب',
      render: (item: any) => (
        <span className="font-semibold text-navy-800">{item.order_number}</span>
      ),
    },
    {
      key: 'customer',
      label: 'العميل',
      render: (item: any) => (
        <div>
          <p className="font-medium text-gray-800">{item.customer?.name ?? '—'}</p>
          <p className="text-[10px] text-gray-400">{item.customer?.customer_code}</p>
        </div>
      ),
    },
    {
      key: 'items_count',
      label: 'القطع',
      render: (item: any) => <span className="text-gray-600">{item.items_count} قطعة</span>,
    },
    {
      key: 'total',
      label: 'المبلغ',
      render: (item: any) => (
        <span className="font-semibold text-gray-800">{item.total?.toFixed(2)} ج.م</span>
      ),
    },
    {
      key: 'status',
      label: 'الحالة',
      render: (item: any) => statusBadge(item.status),
    },
    {
      key: 'created_at',
      label: 'التاريخ',
      render: (item: any) => (
        <span className="text-gray-400 text-xs">
          {new Date(item.created_at).toLocaleDateString('ar-EG')}
        </span>
      ),
    },
  ]

  if (loading) return <SkeletonLoader />

  return (
    <div className="space-y-6">
      <motion.div
        initial={{ opacity: 0, y: -5 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.3 }}
        className="flex items-center justify-between"
      >
        <div>
          <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
            نظرة عامة
            <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-lg bg-primary-50 text-primary-600 text-[10px] font-semibold">
              <Activity size={10} />
              مباشر
            </span>
          </h2>
          <p className="text-sm text-gray-400 mt-0.5">ملخص أداء المنصة</p>
        </div>
      </motion.div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4">
        <StatCard label="إجمالي الإيرادات" value={`${stats.totalRevenue.toLocaleString()} ج.م`} change="+12.5%" changeType="up" icon={DollarSign} color="green" index={0} />
        <StatCard label="إجمالي الطلبات" value={stats.totalOrders} change="+8.7%" changeType="up" icon={ClipboardList} color="blue" index={1} />
        <StatCard label="العملاء" value={stats.totalCustomers} change="-0.4%" changeType="down" icon={Users} color="purple" index={2} />
        <StatCard label="السائقين" value={stats.totalDrivers} icon={Truck} color="orange" index={3} />
        <StatCard label="طلبات نشطة" value={stats.activeOrders} icon={ShoppingBag} color="cyan" index={4} />
        <StatCard label="تم التوصيل" value={stats.deliveredToday} change="+18.3%" changeType="up" icon={TrendingUp} color="green" index={5} />
      </div>

      <motion.div
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.4, delay: 0.3 }}
      >
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-semibold text-gray-800">آخر الطلبات</h3>
          <a href="/orders" className="inline-flex items-center gap-1 text-sm text-primary-500 hover:text-primary-600 font-medium transition-colors">
            عرض الكل
            <ArrowUpLeft size={14} />
          </a>
        </div>
        <DataTable columns={orderColumns} data={recentOrders} emptyMessage="لا توجد طلبات بعد" />
      </motion.div>
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { supabase } from '@/lib/supabase'
import DataTable from '@/components/ui/DataTable'
import Badge from '@/components/ui/Badge'
import Modal from '@/components/ui/Modal'
import { SERVICE_TYPE_LABELS } from '@cleano/shared-types'
import type { ServiceType } from '@cleano/shared-types'
import { Plus, Edit2, Power, Tag } from 'lucide-react'
import { motion } from 'framer-motion'
import { useToast } from '@/components/ui/Toast'
import Tooltip from '@/components/ui/Tooltip'
import PermissionGate from '@/components/ui/PermissionGate'

const serviceVariant: Record<string, 'success' | 'info' | 'purple' | 'warning'> = {
  wash: 'info', iron: 'warning', wash_iron: 'purple', dry_clean: 'success',
}

export default function PricesPage() {
  const [prices, setPrices] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [showAdd, setShowAdd] = useState(false)
  const [editItem, setEditItem] = useState<any>(null)
  const [saving, setSaving] = useState(false)
  const [form, setForm] = useState({ item_type: '', service_type: 'wash', price: 0 })
  const { toast } = useToast()

  useEffect(() => { loadPrices() }, [])

  async function loadPrices() {
    const { data } = await supabase.from('prices').select('id, item_type, service_type, price, is_active').order('item_type')
    setPrices(data ?? [])
    setLoading(false)
  }

  async function handleAdd(e: React.FormEvent) {
    e.preventDefault()
    setSaving(true)
    const { error } = await supabase.from('prices').insert({ ...form, is_active: true })
    setSaving(false)
    if (!error) { setShowAdd(false); setForm({ item_type: '', service_type: 'wash', price: 0 }); loadPrices(); toast('تم إضافة السعر بنجاح') }
    else { toast('حدث خطأ أثناء الإضافة', 'error') }
  }

  async function handleEdit(e: React.FormEvent) {
    e.preventDefault()
    setSaving(true)
    const { error } = await supabase.from('prices').update({ item_type: form.item_type, service_type: form.service_type, price: form.price }).eq('id', editItem.id)
    setSaving(false)
    if (!error) { setEditItem(null); loadPrices(); toast('تم تعديل السعر') }
    else { toast('حدث خطأ أثناء التعديل', 'error') }
  }

  async function toggleActive(id: string, current: boolean) {
    await supabase.from('prices').update({ is_active: !current }).eq('id', id)
    loadPrices()
    toast(current ? 'تم تعطيل السعر' : 'تم تفعيل السعر')
  }

  function openEdit(item: any) {
    setForm({ item_type: item.item_type, service_type: item.service_type, price: item.price })
    setEditItem(item)
  }

  const columns = [
    { key: 'item_type', label: 'نوع القطعة', render: (item: any) => <span className="font-semibold">{item.item_type}</span> },
    { key: 'service_type', label: 'الخدمة', render: (item: any) => (
      <Badge variant={serviceVariant[item.service_type] ?? 'info'}>{SERVICE_TYPE_LABELS[item.service_type as ServiceType] ?? item.service_type}</Badge>
    )},
    { key: 'price', label: 'السعر', render: (item: any) => <span className="font-bold text-primary-600">{item.price} ج.م</span> },
    { key: 'is_active', label: 'الحالة', render: (item: any) => <Badge variant={item.is_active ? 'success' : 'danger'}>{item.is_active ? 'نشط' : 'معطل'}</Badge> },
    { key: 'actions', label: '', render: (item: any) => (
      <div className="flex gap-1">
        <Tooltip content="تعديل"><button onClick={() => openEdit(item)} className="p-1.5 hover:bg-surface-muted rounded-lg transition-colors"><Edit2 size={14} className="text-gray-400" /></button></Tooltip>
        <Tooltip content={item.is_active ? 'تعطيل' : 'تفعيل'}><button onClick={() => toggleActive(item.id, item.is_active)} className="p-1.5 hover:bg-surface-muted rounded-lg transition-colors"><Power size={14} className={item.is_active ? 'text-red-400' : 'text-green-500'} /></button></Tooltip>
      </div>
    )},
  ]

  const formFields = (
    <>
      <div>
        <label className="block text-xs font-medium text-gray-500 mb-1.5">نوع القطعة <span className="text-red-400">*</span></label>
        <input type="text" value={form.item_type} onChange={e => setForm({ ...form, item_type: e.target.value })} required
          placeholder="مثال: قميص، بنطلون، بدلة..." className="w-full p-3 border border-surface-border rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/15 focus:border-primary-500/30 transition-all" />
      </div>
      <div>
        <label className="block text-xs font-medium text-gray-500 mb-1.5">نوع الخدمة <span className="text-red-400">*</span></label>
        <select value={form.service_type} onChange={e => setForm({ ...form, service_type: e.target.value })} required
          className="w-full p-3 border border-surface-border rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/15 focus:border-primary-500/30 transition-all">
          <option value="wash">غسيل</option><option value="iron">كوي</option>
          <option value="wash_iron">غسيل وكوي</option><option value="dry_clean">تنظيف جاف</option>
        </select>
      </div>
      <div>
        <label className="block text-xs font-medium text-gray-500 mb-1.5">السعر (ج.م) <span className="text-red-400">*</span></label>
        <input type="number" min={0} step={0.5} value={form.price} onChange={e => setForm({ ...form, price: +e.target.value })} required
          className="w-full p-3 border border-surface-border rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/15 focus:border-primary-500/30 transition-all" dir="ltr" />
      </div>
    </>
  )

  return (
    <PermissionGate permission="finance.view">
    <div className="space-y-6">
      <motion.div initial={{ opacity: 0, y: -5 }} animate={{ opacity: 1, y: 0 }} className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2"><Tag className="w-5 h-5 text-accent-purple" /> إدارة الأسعار</h2>
          <p className="text-sm text-gray-400 mt-0.5">{prices.length} سعر</p>
        </div>
        <button onClick={() => { setForm({ item_type: '', service_type: 'wash', price: 0 }); setShowAdd(true) }}
          className="flex items-center gap-2 bg-gradient-to-l from-primary-500 to-primary-600 text-white px-4 py-2.5 rounded-xl text-sm font-medium hover:shadow-glow-green transition-all duration-300">
          <Plus size={16} /> سعر جديد
        </button>
      </motion.div>

      {loading ? <div className="flex items-center justify-center h-32"><div className="w-6 h-6 border-3 border-primary-500 border-t-transparent rounded-full animate-spin" /></div>
        : <DataTable columns={columns} data={prices} emptyMessage="لا توجد أسعار" />}

      <Modal open={showAdd} onClose={() => setShowAdd(false)} title="سعر جديد">
        <form onSubmit={handleAdd} className="space-y-4">
          {formFields}
          <button type="submit" disabled={saving} className="w-full bg-gradient-to-l from-primary-500 to-primary-600 text-white p-3 rounded-xl font-semibold hover:shadow-glow-green disabled:opacity-50 transition-all">
            {saving ? 'جاري الحفظ...' : 'إضافة السعر'}
          </button>
        </form>
      </Modal>

      <Modal open={!!editItem} onClose={() => setEditItem(null)} title="تعديل السعر">
        <form onSubmit={handleEdit} className="space-y-4">
          {formFields}
          <button type="submit" disabled={saving} className="w-full bg-gradient-to-l from-primary-500 to-primary-600 text-white p-3 rounded-xl font-semibold hover:shadow-glow-green disabled:opacity-50 transition-all">
            {saving ? 'جاري الحفظ...' : 'حفظ التعديلات'}
          </button>
        </form>
      </Modal>
    </div>
    </PermissionGate>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { supabase } from '@/lib/supabase'
import { motion } from 'framer-motion'
import { Star, MessageSquare, TrendingUp, Users } from 'lucide-react'
import DataTable from '@/components/ui/DataTable'
import Badge from '@/components/ui/Badge'
import { TableSkeleton } from '@/components/ui/Skeleton'
import PermissionGate from '@/components/ui/PermissionGate'

export default function RatingsPage() {
  const [ratings, setRatings] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [stats, setStats] = useState({ total: 0, avgService: 0, avgDriver: 0, withNotes: 0 })
  const [filter, setFilter] = useState<'all' | 'with_notes' | 'low'>('all')
  const [page, setPage] = useState(0)
  const [totalCount, setTotalCount] = useState(0)
  const PAGE_SIZE = 20

  useEffect(() => { loadRatings() }, [page, filter])
  useEffect(() => { loadStats() }, [])

  async function loadStats() {
    const { data } = await supabase
      .from('orders')
      .select('rating_service, rating_driver, rating_note')
      .not('rated_at', 'is', null)

    if (data && data.length > 0) {
      const total = data.length
      const avgService = data.reduce((sum, r) => sum + (r.rating_service || 0), 0) / total
      const avgDriver = data.filter(r => r.rating_driver).reduce((sum, r) => sum + r.rating_driver, 0) / (data.filter(r => r.rating_driver).length || 1)
      const withNotes = data.filter(r => r.rating_note).length
      setStats({ total, avgService: Math.round(avgService * 10) / 10, avgDriver: Math.round(avgDriver * 10) / 10, withNotes })
    }
  }

  async function loadRatings() {
    let query = supabase
      .from('orders')
      .select('id, order_number, rating_service, rating_driver, rating_note, rated_at, customer:users!orders_customer_id_fkey(name, phone), driver:users!orders_driver_id_fkey(name)', { count: 'exact' })
      .not('rated_at', 'is', null)
      .order('rated_at', { ascending: false })

    if (filter === 'with_notes') {
      query = query.not('rating_note', 'is', null).neq('rating_note', '')
    } else if (filter === 'low') {
      query = query.lte('rating_service', 2)
    }

    const { data, count } = await query.range(page * PAGE_SIZE, (page + 1) * PAGE_SIZE - 1)
    setRatings(data ?? [])
    setTotalCount(count ?? 0)
    setLoading(false)
  }

  function renderStars(count: number) {
    return '⭐'.repeat(count) + '☆'.repeat(5 - count)
  }

  const columns = [
    {
      key: 'order_number',
      label: 'رقم الطلب',
      render: (item: any) => <span className="font-semibold text-gray-800">{item.order_number}</span>,
    },
    {
      key: 'customer',
      label: 'العميل',
      render: (item: any) => (
        <div>
          <p className="font-medium text-gray-800">{item.customer?.name ?? '—'}</p>
          <p className="text-[10px] text-gray-400">{item.customer?.phone}</p>
        </div>
      ),
    },
    {
      key: 'rating_service',
      label: 'تقييم الخدمة',
      render: (item: any) => (
        <div className="flex items-center gap-1">
          <span className="text-sm">{renderStars(item.rating_service)}</span>
          <span className="text-xs font-bold text-gray-600 mr-1">{item.rating_service}/5</span>
        </div>
      ),
    },
    {
      key: 'rating_driver',
      label: 'تقييم السائق',
      render: (item: any) => item.rating_driver ? (
        <div>
          <span className="text-sm">{renderStars(item.rating_driver)}</span>
          <span className="text-xs font-bold text-gray-600 mr-1">{item.rating_driver}/5</span>
          {item.driver?.name && <p className="text-[10px] text-gray-400 mt-0.5">{item.driver.name}</p>}
        </div>
      ) : <span className="text-gray-300 text-xs">—</span>,
    },
    {
      key: 'rating_note',
      label: 'ملاحظات',
      render: (item: any) => item.rating_note ? (
        <p className="text-xs text-gray-600 max-w-[200px] line-clamp-2">{item.rating_note}</p>
      ) : <span className="text-gray-300 text-xs">—</span>,
    },
    {
      key: 'rated_at',
      label: 'التاريخ',
      render: (item: any) => (
        <div>
          <span className="text-xs text-gray-600">
            {new Date(item.rated_at).toLocaleDateString('ar-EG', { year: 'numeric', month: 'short', day: 'numeric' })}
          </span>
          <p className="text-[10px] text-gray-400">
            {new Date(item.rated_at).toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' })}
          </p>
        </div>
      ),
    },
  ]

  const totalPages = Math.ceil(totalCount / PAGE_SIZE)

  return (
    <PermissionGate permission="orders.view">
      <div className="space-y-6">
        <motion.div initial={{ opacity: 0, y: -5 }} animate={{ opacity: 1, y: 0 }}>
          <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
            <Star className="w-5 h-5 text-yellow-500" />
            التقييمات
          </h2>
          <p className="text-sm text-gray-400 mt-0.5">تقييمات العملاء للطلبات والسواقين</p>
        </motion.div>

        {/* Stats */}
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="grid grid-cols-2 md:grid-cols-4 gap-4"
        >
          <StatCard icon={<Star size={18} className="text-yellow-500" />} label="إجمالي التقييمات" value={stats.total} />
          <StatCard icon={<TrendingUp size={18} className="text-emerald-500" />} label="متوسط تقييم الخدمة" value={`${stats.avgService} / 5`} />
          <StatCard icon={<Users size={18} className="text-blue-500" />} label="متوسط تقييم السائق" value={`${stats.avgDriver} / 5`} />
          <StatCard icon={<MessageSquare size={18} className="text-purple-500" />} label="تقييمات بملاحظات" value={stats.withNotes} />
        </motion.div>

        {/* Filters */}
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.15 }}
          className="flex gap-2"
        >
          {([
            { key: 'all', label: 'الكل' },
            { key: 'with_notes', label: 'بملاحظات' },
            { key: 'low', label: 'تقييم منخفض (1-2)' },
          ] as { key: typeof filter; label: string }[]).map(f => (
            <button
              key={f.key}
              onClick={() => { setFilter(f.key); setPage(0) }}
              className={`px-4 py-2 rounded-xl text-xs font-medium transition-all ${
                filter === f.key
                  ? 'bg-navy-900 text-white shadow-premium-md'
                  : 'bg-white text-gray-500 hover:bg-surface-muted border border-surface-border/60'
              }`}
            >
              {f.label}
            </button>
          ))}
        </motion.div>

        {/* Table */}
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
        >
          {loading ? (
            <TableSkeleton />
          ) : (
            <>
              <DataTable columns={columns} data={ratings} emptyMessage="لا توجد تقييمات بعد" />
              {totalPages > 1 && (
                <div className="flex items-center justify-center gap-2 mt-4">
                  <button
                    onClick={() => setPage(p => Math.max(0, p - 1))}
                    disabled={page === 0}
                    className="px-3 py-1.5 rounded-lg text-xs font-medium bg-white border border-surface-border/60 disabled:opacity-40"
                  >
                    السابق
                  </button>
                  <span className="text-xs text-gray-500">{page + 1} / {totalPages}</span>
                  <button
                    onClick={() => setPage(p => Math.min(totalPages - 1, p + 1))}
                    disabled={page >= totalPages - 1}
                    className="px-3 py-1.5 rounded-lg text-xs font-medium bg-white border border-surface-border/60 disabled:opacity-40"
                  >
                    التالي
                  </button>
                </div>
              )}
            </>
          )}
        </motion.div>
      </div>
    </PermissionGate>
  )
}

function StatCard({ icon, label, value }: { icon: React.ReactNode; label: string; value: string | number }) {
  return (
    <div className="bg-white rounded-2xl border border-surface-border/60 p-4 flex flex-col items-center gap-2">
      <div className="w-9 h-9 rounded-xl bg-surface-muted flex items-center justify-center">{icon}</div>
      <span className="text-lg font-bold text-gray-800">{value}</span>
      <span className="text-[11px] text-gray-400">{label}</span>
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { supabase } from '@/lib/supabase'
import { BarChart3, TrendingUp, Users, Truck, Calendar, RotateCcw } from 'lucide-react'
import { motion } from 'framer-motion'
import StatCard from '@/components/ui/StatCard'
import PermissionGate from '@/components/ui/PermissionGate'

const today = () => new Date().toISOString().split('T')[0]
const monthStart = () => { const d = new Date(); d.setDate(1); return d.toISOString().split('T')[0] }

type DatePreset = 'all' | 'today' | 'week' | 'month' | 'custom'

export default function ReportsPage() {
  const [stats, setStats] = useState({ totalOrders: 0, totalRevenue: 0, totalCustomers: 0, totalDrivers: 0, ordersByStatus: {} as Record<string, number>, ordersByService: {} as Record<string, number> })
  const [loading, setLoading] = useState(true)
  const [preset, setPreset] = useState<DatePreset>('all')
  const [dateFrom, setDateFrom] = useState('')
  const [dateTo, setDateTo] = useState('')

  useEffect(() => { load() }, [preset, dateFrom, dateTo])

  function getDateRange(): { from: string | null; to: string | null } {
    const now = new Date()
    switch (preset) {
      case 'today':
        return { from: today() + 'T00:00:00', to: today() + 'T23:59:59' }
      case 'week': {
        const w = new Date(now)
        w.setDate(now.getDate() - 7)
        return { from: w.toISOString(), to: now.toISOString() }
      }
      case 'month':
        return { from: monthStart() + 'T00:00:00', to: now.toISOString() }
      case 'custom':
        return { from: dateFrom ? dateFrom + 'T00:00:00' : null, to: dateTo ? dateTo + 'T23:59:59' : null }
      default:
        return { from: null, to: null }
    }
  }

  async function load() {
    let query = supabase.from('orders').select('status, service_type, total, created_at')
    const { from, to } = getDateRange()
    if (from) query = query.gte('created_at', from)
    if (to) query = query.lte('created_at', to)

    const [orders, customers, drivers] = await Promise.all([
      query,
      supabase.from('users').select('id', { count: 'exact', head: true }).eq('role', 'customer'),
      supabase.from('users').select('id', { count: 'exact', head: true }).eq('role', 'driver'),
    ])

    const orderData = orders.data ?? []
    const totalRevenue = orderData.reduce((s, o) => s + (o.total ?? 0), 0)
    const ordersByStatus: Record<string, number> = {}
    const ordersByService: Record<string, number> = {}
    orderData.forEach(o => {
      ordersByStatus[o.status] = (ordersByStatus[o.status] ?? 0) + 1
      ordersByService[o.service_type] = (ordersByService[o.service_type] ?? 0) + 1
    })

    setStats({ totalOrders: orderData.length, totalRevenue, totalCustomers: customers.count ?? 0, totalDrivers: drivers.count ?? 0, ordersByStatus, ordersByService })
    setLoading(false)
  }

  function resetFilters() {
    setPreset('all')
    setDateFrom('')
    setDateTo('')
  }

  const statusLabel: Record<string, string> = { pending: 'في الانتظار', assigned: 'تم التعيين', picked_up: 'تم الاستلام', processing: 'جاري المعالجة', ready: 'جاهز', delivering: 'جاري التوصيل', delivered: 'تم التوصيل', cancelled: 'ملغي' }
  const serviceLabel: Record<string, string> = { wash: 'غسيل', iron: 'كوي', wash_iron: 'غسيل وكوي', dry_clean: 'تنظيف جاف' }
  const presets: { key: DatePreset; label: string }[] = [
    { key: 'all', label: 'الكل' }, { key: 'today', label: 'اليوم' },
    { key: 'week', label: 'آخر أسبوع' }, { key: 'month', label: 'هذا الشهر' },
    { key: 'custom', label: 'مخصص' },
  ]

  const inputClass = 'px-3 py-2 bg-white border border-surface-border/60 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/15 transition-all'

  if (loading) return <div className="flex items-center justify-center h-64"><div className="w-8 h-8 border-4 border-primary-500 border-t-transparent rounded-full animate-spin" /></div>

  return (
    <PermissionGate permission="reports.view">
    <div className="space-y-6">
      <motion.div initial={{ opacity: 0, y: -5 }} animate={{ opacity: 1, y: 0 }} className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2"><BarChart3 className="w-5 h-5 text-blue-500" /> التقارير</h2>
          <p className="text-sm text-gray-400 mt-0.5">تقارير الأداء والإحصائيات</p>
        </div>
        {preset !== 'all' && (
          <button onClick={resetFilters} className="flex items-center gap-1.5 text-sm text-gray-500 hover:text-primary-500 transition-colors">
            <RotateCcw size={14} /> إعادة تعيين
          </button>
        )}
      </motion.div>

      {/* Date filters */}
      <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.05 }} className="flex flex-wrap items-center gap-3">
        <Calendar size={16} className="text-gray-400" />
        <div className="flex gap-1.5">
          {presets.map(p => (
            <button key={p.key} onClick={() => setPreset(p.key)}
              className={`px-3 py-2 rounded-lg text-[11px] font-medium transition-all ${preset === p.key ? 'bg-navy-900 text-white shadow-premium-md' : 'bg-white text-gray-500 hover:bg-surface-muted border border-surface-border/60'}`}>
              {p.label}
            </button>
          ))}
        </div>
        {preset === 'custom' && (
          <div className="flex items-center gap-2">
            <input type="date" value={dateFrom} onChange={e => setDateFrom(e.target.value)} className={inputClass} />
            <span className="text-gray-400 text-xs">إلى</span>
            <input type="date" value={dateTo} onChange={e => setDateTo(e.target.value)} className={inputClass} />
          </div>
        )}
      </motion.div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <StatCard label="إجمالي الطلبات" value={stats.totalOrders} icon={BarChart3} color="blue" />
        <StatCard label="إجمالي الإيرادات" value={`${stats.totalRevenue.toFixed(0)} ج.م`} icon={TrendingUp} color="green" />
        <StatCard label="العملاء" value={stats.totalCustomers} icon={Users} color="purple" />
        <StatCard label="السائقين" value={stats.totalDrivers} icon={Truck} color="orange" />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-white rounded-2xl shadow-premium border border-surface-border/60 p-6">
          <h3 className="font-semibold text-gray-800 mb-4">الطلبات حسب الحالة</h3>
          <div className="space-y-3">
            {Object.entries(stats.ordersByStatus).map(([status, count]) => (
              <div key={status} className="flex items-center justify-between">
                <span className="text-sm text-gray-600">{statusLabel[status] ?? status}</span>
                <div className="flex items-center gap-3">
                  <div className="w-32 h-2 bg-gray-100 rounded-full overflow-hidden">
                    <div className="h-full bg-primary-500 rounded-full" style={{ width: `${stats.totalOrders ? (count / stats.totalOrders) * 100 : 0}%` }} />
                  </div>
                  <span className="text-sm font-bold text-gray-800 w-8 text-left">{count}</span>
                </div>
              </div>
            ))}
            {Object.keys(stats.ordersByStatus).length === 0 && <p className="text-sm text-gray-400 text-center py-4">لا توجد بيانات</p>}
          </div>
        </div>

        <div className="bg-white rounded-2xl shadow-premium border border-surface-border/60 p-6">
          <h3 className="font-semibold text-gray-800 mb-4">الطلبات حسب الخدمة</h3>
          <div className="space-y-3">
            {Object.entries(stats.ordersByService).map(([service, count]) => (
              <div key={service} className="flex items-center justify-between">
                <span className="text-sm text-gray-600">{serviceLabel[service] ?? service}</span>
                <div className="flex items-center gap-3">
                  <div className="w-32 h-2 bg-gray-100 rounded-full overflow-hidden">
                    <div className="h-full bg-accent-purple rounded-full" style={{ width: `${stats.totalOrders ? (count / stats.totalOrders) * 100 : 0}%` }} />
                  </div>
                  <span className="text-sm font-bold text-gray-800 w-8 text-left">{count}</span>
                </div>
              </div>
            ))}
            {Object.keys(stats.ordersByService).length === 0 && <p className="text-sm text-gray-400 text-center py-4">لا توجد بيانات</p>}
          </div>
        </div>
      </div>
    </div>
    </PermissionGate>
  )
}

'use client'

import { useEffect, useState, useRef } from 'react'
import { supabase } from '@/lib/supabase'
import { Settings, Save, Plus, Trash2, UserCircle, Mail, Lock, Camera, Eye, EyeOff, Check, Users } from 'lucide-react'
import { motion } from 'framer-motion'
import Modal from '@/components/ui/Modal'
import { useToast } from '@/components/ui/Toast'
import UsersTab from '@/components/settings/UsersTab'
import PermissionGate from '@/components/ui/PermissionGate'

const tabs = [
  { key: 'general', label: 'عام', icon: Settings },
  { key: 'users', label: 'المستخدمين', icon: Users },
  { key: 'profile', label: 'الملف الشخصي', icon: UserCircle },
  { key: 'security', label: 'الأمان', icon: Lock },
]

export default function SettingsPage() {
  const [activeTab, setActiveTab] = useState('general')
  const [settings, setSettings] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [orgName, setOrgName] = useState('Laundry Bag')
  const [orgPhone, setOrgPhone] = useState('+201000000000')
  const [editValues, setEditValues] = useState<Record<string, string>>({})
  const [showAdd, setShowAdd] = useState(false)
  const [newSetting, setNewSetting] = useState({ key: '', value: '', description: '' })
  const { toast } = useToast()

  // Profile states
  const [profile, setProfile] = useState<any>(null)
  const [userId, setUserId] = useState('')
  const [userEmail, setUserEmail] = useState('')
  const [name, setName] = useState('')
  const [phone, setPhone] = useState('')
  const [savingProfile, setSavingProfile] = useState(false)
  const [newEmail, setNewEmail] = useState('')
  const [savingEmail, setSavingEmail] = useState(false)
  const [newPassword, setNewPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [showNew, setShowNew] = useState(false)
  const [savingPassword, setSavingPassword] = useState(false)
  const [avatarUrl, setAvatarUrl] = useState<string | null>(null)
  const [uploading, setUploading] = useState(false)
  const fileRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    loadSettings()
    loadProfile()
  }, [])

  async function loadSettings() {
    const { data } = await supabase.from('settings').select('id, key, value, description').order('key')
    setSettings(data ?? [])
    const vals: Record<string, string> = {}
    data?.forEach(s => { vals[s.id] = typeof s.value === 'object' ? JSON.stringify(s.value) : String(s.value) })
    setEditValues(vals)
    const nameS = data?.find(s => s.key === 'org_name')
    const phoneS = data?.find(s => s.key === 'org_phone')
    if (nameS) setOrgName(String(nameS.value))
    if (phoneS) setOrgPhone(String(phoneS.value))
    setLoading(false)
  }

  async function loadProfile() {
    const { data: { user } } = await supabase.auth.getUser()
    if (!user) return
    setUserId(user.id)
    setUserEmail(user.email ?? '')
    setNewEmail(user.email ?? '')
    const { data } = await supabase.from('users').select('id, name, phone, email, role, avatar_url').eq('id', user.id).single()
    if (data) {
      setProfile(data)
      setName(data.name || '')
      setPhone(data.phone || '')
      setAvatarUrl(data.avatar_url || null)
    }
  }

  async function handleSaveAll() {
    setSaving(true)
    const upsertData = settings.map(s => ({ id: s.id, key: s.key, value: editValues[s.id] ?? s.value, description: s.description }))
    const nameExists = settings.find(s => s.key === 'org_name')
    const phoneExists = settings.find(s => s.key === 'org_phone')
    if (nameExists) upsertData.push({ id: nameExists.id, key: 'org_name', value: orgName, description: nameExists.description })
    if (phoneExists) upsertData.push({ id: phoneExists.id, key: 'org_phone', value: orgPhone, description: phoneExists.description })
    await supabase.from('settings').upsert(upsertData)
    if (!nameExists) await supabase.from('settings').upsert({ key: 'org_name', value: orgName, description: 'اسم المؤسسة' })
    if (!phoneExists) await supabase.from('settings').upsert({ key: 'org_phone', value: orgPhone, description: 'رقم هاتف المؤسسة' })
    setSaving(false)
    loadSettings()
    toast('تم حفظ الإعدادات بنجاح')
  }

  async function handleAddSetting(e: React.FormEvent) {
    e.preventDefault()
    await supabase.from('settings').insert({ key: newSetting.key, value: newSetting.value, description: newSetting.description || null })
    setShowAdd(false)
    setNewSetting({ key: '', value: '', description: '' })
    loadSettings()
    toast('تم إضافة الإعداد')
  }

  async function deleteSetting(id: string) {
    await supabase.from('settings').delete().eq('id', id)
    loadSettings()
    toast('تم حذف الإعداد')
  }

  async function handleSaveProfile(e: React.FormEvent) {
    e.preventDefault()
    setSavingProfile(true)
    const { error } = await supabase.from('users').update({ name, phone }).eq('id', userId)
    setSavingProfile(false)
    if (!error) { setProfile((p: any) => ({ ...p, name, phone })); toast('تم تحديث البيانات الشخصية') }
    else toast('حدث خطأ في التحديث', 'error')
  }

  async function handleChangeEmail(e: React.FormEvent) {
    e.preventDefault()
    if (newEmail === userEmail) return toast('الإيميل هو نفسه الحالي', 'warning')
    setSavingEmail(true)
    const { error } = await supabase.auth.updateUser({ email: newEmail })
    setSavingEmail(false)
    if (!error) toast('تم إرسال رابط التأكيد للإيميل الجديد')
    else toast(error.message || 'حدث خطأ', 'error')
  }

  async function handleChangePassword(e: React.FormEvent) {
    e.preventDefault()
    if (newPassword.length < 6) return toast('كلمة المرور يجب أن تكون 6 أحرف على الأقل', 'warning')
    if (newPassword !== confirmPassword) return toast('كلمة المرور غير متطابقة', 'warning')
    setSavingPassword(true)
    const { error } = await supabase.auth.updateUser({ password: newPassword })
    setSavingPassword(false)
    if (!error) { setNewPassword(''); setConfirmPassword(''); toast('تم تغيير كلمة المرور') }
    else toast(error.message || 'حدث خطأ', 'error')
  }

  async function handleAvatarUpload(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0]
    if (!file) return
    if (file.size > 2 * 1024 * 1024) return toast('الحد الأقصى 2 ميجا', 'warning')
    setUploading(true)
    const ext = file.name.split('.').pop()
    const path = `avatars/${userId}.${ext}`
    const { error: uploadError } = await supabase.storage.from('avatars').upload(path, file, { upsert: true })
    if (uploadError) { setUploading(false); toast('فشل رفع الصورة', 'error'); return }
    const { data: { publicUrl } } = supabase.storage.from('avatars').getPublicUrl(path)
    const url = `${publicUrl}?t=${Date.now()}`
    await supabase.from('users').update({ avatar_url: url }).eq('id', userId)
    setAvatarUrl(url)
    setProfile((p: any) => ({ ...p, avatar_url: url }))
    setUploading(false)
    toast('تم تحديث الصورة الشخصية')
  }

  const inputClass = 'w-full p-3 border border-surface-border rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/15 focus:border-primary-500/30 transition-all'
  const sectionClass = 'bg-white rounded-2xl shadow-premium border border-surface-border/60 overflow-hidden'

  if (loading) return <div className="flex items-center justify-center h-64"><div className="w-8 h-8 border-4 border-primary-500 border-t-transparent rounded-full animate-spin" /></div>

  return (
    <PermissionGate permission="settings.view">
    <div className="space-y-6">
      <motion.div initial={{ opacity: 0, y: -5 }} animate={{ opacity: 1, y: 0 }} className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2"><Settings className="w-5 h-5 text-gray-500" /> الإعدادات</h2>
          <p className="text-sm text-gray-400 mt-0.5">إعدادات المنصة والحساب الشخصي</p>
        </div>
      </motion.div>

      {/* Tabs */}
      <div className="flex gap-1.5 bg-surface-muted/60 p-1 rounded-xl w-fit">
        {tabs.map(t => {
          const Icon = t.icon
          return (
            <button key={t.key} onClick={() => setActiveTab(t.key)}
              className={`flex items-center gap-1.5 px-4 py-2 rounded-lg text-sm font-medium transition-all ${activeTab === t.key ? 'bg-white text-gray-800 shadow-premium-md' : 'text-gray-500 hover:text-gray-700'}`}>
              <Icon size={14} /> {t.label}
            </button>
          )
        })}
      </div>

      {/* General Tab */}
      {activeTab === 'general' && (
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-6">
          <div className="flex justify-end gap-2">
            <button onClick={() => setShowAdd(true)} className="flex items-center gap-2 bg-white border border-surface-border/60 text-gray-600 px-4 py-2.5 rounded-xl text-sm font-medium hover:bg-surface-muted transition-colors">
              <Plus size={16} /> إعداد جديد
            </button>
            <button onClick={handleSaveAll} disabled={saving}
              className="flex items-center gap-2 bg-gradient-to-l from-primary-500 to-primary-600 text-white px-4 py-2.5 rounded-xl text-sm font-medium hover:shadow-glow-green disabled:opacity-50 transition-all duration-300">
              <Save size={16} /> {saving ? 'جاري الحفظ...' : 'حفظ الكل'}
            </button>
          </div>

          <div className={sectionClass + ' p-6'}>
            <div className="flex items-center gap-3 mb-6">
              <div className="p-2 bg-navy-50 rounded-xl"><Settings size={20} className="text-navy-600" /></div>
              <h3 className="font-semibold text-gray-800">معلومات المؤسسة</h3>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="block text-sm font-medium text-gray-600 mb-1">اسم المؤسسة</label>
                <input type="text" value={orgName} onChange={e => setOrgName(e.target.value)} className={inputClass} />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-600 mb-1">رقم الهاتف</label>
                <input type="text" value={orgPhone} onChange={e => setOrgPhone(e.target.value)} dir="ltr" className={inputClass} />
              </div>
            </div>
          </div>

          <div className={sectionClass + ' p-6'}>
            <h3 className="font-semibold text-gray-800 mb-4">إعدادات النظام</h3>
            <div className="space-y-4">
              {settings.filter(s => s.key !== 'org_name' && s.key !== 'org_phone').map(s => (
                <div key={s.id} className="flex items-center gap-4 py-3 border-b border-gray-50 last:border-0">
                  <div className="flex-1">
                    <p className="text-sm font-medium text-gray-700">{s.description ?? s.key}</p>
                    <p className="text-xs text-gray-400">{s.key}</p>
                  </div>
                  <input type="text" value={editValues[s.id] ?? ''} onChange={e => setEditValues({ ...editValues, [s.id]: e.target.value })}
                    className="w-48 p-2 border border-gray-200 rounded-lg text-sm text-left focus:outline-none focus:ring-2 focus:ring-primary-500/20" dir="ltr" />
                  <button onClick={() => deleteSetting(s.id)} className="p-1.5 hover:bg-red-50 rounded-lg transition-colors"><Trash2 size={14} className="text-red-400" /></button>
                </div>
              ))}
              {settings.filter(s => s.key !== 'org_name' && s.key !== 'org_phone').length === 0 && (
                <p className="text-sm text-gray-400 text-center py-4">لا توجد إعدادات إضافية</p>
              )}
            </div>
          </div>
        </motion.div>
      )}

      {/* Users Tab */}
      {activeTab === 'users' && <UsersTab />}

      {/* Profile Tab */}
      {activeTab === 'profile' && (
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-6 max-w-3xl">
          {/* Avatar header */}
          <div className={sectionClass}>
            <div className="bg-gradient-to-l from-primary-500/10 via-accent-purple/5 to-transparent p-6">
              <div className="flex items-center gap-5">
                <div className="relative group">
                  <div className="w-20 h-20 rounded-2xl bg-gradient-to-br from-primary-400 to-accent-purple/80 flex items-center justify-center text-white text-2xl font-bold shadow-premium-lg overflow-hidden">
                    {avatarUrl ? <img src={avatarUrl} alt="avatar" className="w-full h-full object-cover" /> : profile?.name?.[0] ?? '?'}
                  </div>
                  <button onClick={() => fileRef.current?.click()} disabled={uploading}
                    className="absolute inset-0 rounded-2xl bg-black/0 group-hover:bg-black/40 flex items-center justify-center transition-all cursor-pointer">
                    <Camera size={20} className="text-white opacity-0 group-hover:opacity-100 transition-opacity" />
                  </button>
                  <input ref={fileRef} type="file" accept="image/*" onChange={handleAvatarUpload} className="hidden" />
                  {uploading && (
                    <div className="absolute inset-0 rounded-2xl bg-black/50 flex items-center justify-center">
                      <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin" />
                    </div>
                  )}
                </div>
                <div>
                  <h3 className="text-lg font-bold text-gray-800">{profile?.name}</h3>
                  <p className="text-sm text-gray-400">{userEmail}</p>
                  <p className="text-xs text-primary-500 mt-1 font-medium">{profile?.role === 'admin' ? 'مدير النظام' : profile?.role}</p>
                </div>
              </div>
            </div>
          </div>

          {/* Personal info */}
          <div className={sectionClass}>
            <div className="px-6 py-4 border-b border-surface-border/60 flex items-center gap-2">
              <UserCircle size={16} className="text-primary-500" />
              <h3 className="font-semibold text-gray-800 text-sm">البيانات الشخصية</h3>
            </div>
            <form onSubmit={handleSaveProfile} className="p-6 space-y-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-medium text-gray-500 mb-1.5">الاسم</label>
                  <input type="text" value={name} onChange={e => setName(e.target.value)} required className={inputClass} />
                </div>
                <div>
                  <label className="block text-xs font-medium text-gray-500 mb-1.5">رقم الهاتف</label>
                  <input type="text" value={phone} onChange={e => setPhone(e.target.value)} className={inputClass} placeholder="01xxxxxxxxx" />
                </div>
              </div>
              <div className="flex justify-end">
                <button type="submit" disabled={savingProfile}
                  className="flex items-center gap-2 bg-gradient-to-l from-primary-500 to-primary-600 text-white px-5 py-2.5 rounded-xl text-sm font-medium hover:shadow-glow-green disabled:opacity-50 transition-all">
                  <Save size={14} /> {savingProfile ? 'جاري الحفظ...' : 'حفظ التعديلات'}
                </button>
              </div>
            </form>
          </div>

          {/* Email change */}
          <div className={sectionClass}>
            <div className="px-6 py-4 border-b border-surface-border/60 flex items-center gap-2">
              <Mail size={16} className="text-blue-500" />
              <h3 className="font-semibold text-gray-800 text-sm">تغيير البريد الإلكتروني</h3>
            </div>
            <form onSubmit={handleChangeEmail} className="p-6 space-y-4">
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1.5">البريد الحالي</label>
                <input type="email" value={userEmail} disabled className={inputClass + ' bg-surface-muted/50 text-gray-400 cursor-not-allowed'} />
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1.5">البريد الجديد</label>
                <input type="email" value={newEmail} onChange={e => setNewEmail(e.target.value)} required className={inputClass} />
              </div>
              <p className="text-[11px] text-gray-400">سيتم إرسال رابط تأكيد للإيميل الجديد لتفعيل التغيير</p>
              <div className="flex justify-end">
                <button type="submit" disabled={savingEmail || newEmail === userEmail}
                  className="flex items-center gap-2 bg-gradient-to-l from-blue-500 to-blue-600 text-white px-5 py-2.5 rounded-xl text-sm font-medium hover:shadow-lg disabled:opacity-50 transition-all">
                  <Mail size={14} /> {savingEmail ? 'جاري الإرسال...' : 'تغيير الإيميل'}
                </button>
              </div>
            </form>
          </div>
        </motion.div>
      )}

      {/* Security Tab */}
      {activeTab === 'security' && (
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-6 max-w-3xl">
          <div className={sectionClass}>
            <div className="px-6 py-4 border-b border-surface-border/60 flex items-center gap-2">
              <Lock size={16} className="text-amber-500" />
              <h3 className="font-semibold text-gray-800 text-sm">تغيير كلمة المرور</h3>
            </div>
            <form onSubmit={handleChangePassword} className="p-6 space-y-4">
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1.5">كلمة المرور الجديدة</label>
                <div className="relative">
                  <input type={showNew ? 'text' : 'password'} value={newPassword} onChange={e => setNewPassword(e.target.value)} required minLength={6} className={inputClass + ' pl-10'} placeholder="6 أحرف على الأقل" />
                  <button type="button" onClick={() => setShowNew(!showNew)} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600">
                    {showNew ? <EyeOff size={16} /> : <Eye size={16} />}
                  </button>
                </div>
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1.5">تأكيد كلمة المرور</label>
                <div className="relative">
                  <input type="password" value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)} required className={inputClass + ' pl-10'} />
                  {confirmPassword && confirmPassword === newPassword && <Check size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-emerald-500" />}
                </div>
                {confirmPassword && confirmPassword !== newPassword && <p className="text-[11px] text-red-400 mt-1">كلمة المرور غير متطابقة</p>}
              </div>
              {newPassword && (
                <div className="space-y-1.5">
                  <div className="flex gap-1">
                    {[1, 2, 3, 4].map(i => {
                      const strength = newPassword.length >= 12 ? 4 : newPassword.length >= 8 ? 3 : newPassword.length >= 6 ? 2 : 1
                      return <div key={i} className={`h-1 flex-1 rounded-full transition-colors ${i <= strength ? (strength >= 3 ? 'bg-emerald-400' : strength >= 2 ? 'bg-amber-400' : 'bg-red-400') : 'bg-gray-100'}`} />
                    })}
                  </div>
                  <p className="text-[10px] text-gray-400">{newPassword.length >= 12 ? 'قوية جداً' : newPassword.length >= 8 ? 'جيدة' : newPassword.length >= 6 ? 'مقبولة' : 'ضعيفة'}</p>
                </div>
              )}
              <div className="flex justify-end">
                <button type="submit" disabled={savingPassword || !newPassword || newPassword !== confirmPassword}
                  className="flex items-center gap-2 bg-gradient-to-l from-amber-500 to-amber-600 text-white px-5 py-2.5 rounded-xl text-sm font-medium hover:shadow-lg disabled:opacity-50 transition-all">
                  <Lock size={14} /> {savingPassword ? 'جاري التغيير...' : 'تغيير كلمة المرور'}
                </button>
              </div>
            </form>
          </div>
        </motion.div>
      )}

      <Modal open={showAdd} onClose={() => setShowAdd(false)} title="إعداد جديد">
        <form onSubmit={handleAddSetting} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-600 mb-1">المفتاح (Key)</label>
            <input type="text" value={newSetting.key} onChange={e => setNewSetting({ ...newSetting, key: e.target.value })} required dir="ltr"
              placeholder="e.g. delivery_fee" className={inputClass} />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-600 mb-1">القيمة</label>
            <input type="text" value={newSetting.value} onChange={e => setNewSetting({ ...newSetting, value: e.target.value })} required dir="ltr" className={inputClass} />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-600 mb-1">الوصف</label>
            <input type="text" value={newSetting.description} onChange={e => setNewSetting({ ...newSetting, description: e.target.value })}
              placeholder="وصف اختياري..." className={inputClass} />
          </div>
          <button type="submit" className="w-full bg-primary-500 text-white p-3 rounded-xl font-semibold hover:bg-primary-600 transition">إضافة الإعداد</button>
        </form>
      </Modal>
    </div>
    </PermissionGate>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { motion } from 'framer-motion'
import { supabase } from '@/lib/supabase'
import DataTable from '@/components/ui/DataTable'
import Badge from '@/components/ui/Badge'
import Modal from '@/components/ui/Modal'
import { Crown, Eye, Check, X, Plus, Edit2, Trash2 } from 'lucide-react'
import { TableSkeleton } from '@/components/ui/Skeleton'
import { useToast } from '@/components/ui/Toast'
import PermissionGate from '@/components/ui/PermissionGate'

const statusVariant: Record<string, 'success' | 'warning' | 'danger' | 'info' | 'neutral'> = {
  active: 'success',
  pending: 'warning',
  cancelled: 'danger',
  expired: 'neutral',
  paused: 'info',
}

const statusLabels: Record<string, string> = {
  active: 'نشط',
  pending: 'في الانتظار',
  cancelled: 'ملغي',
  expired: 'منتهي',
  paused: 'متوقف',
}

const durationLabels: Record<string, string> = {
  monthly: 'شهري',
  quarterly: 'ربع سنوي',
  biannual: 'نصف سنوي',
  annual: 'سنوي',
}

const emptyForm = {
  user_id: '',
  plan_id: '',
  duration: 'monthly',
  status: 'pending',
  items_used: 0,
  items_limit: 0,
  payment_method: 'cash',
  total_paid: 0,
  auto_renew: false,
}

export default function SubscriptionsPage() {
  const [subs, setSubs] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [statusFilter, setStatusFilter] = useState('all')
  const [detail, setDetail] = useState<any>(null)
  const [showAdd, setShowAdd] = useState(false)
  const [editSub, setEditSub] = useState<any>(null)
  const [saving, setSaving] = useState(false)
  const [form, setForm] = useState(emptyForm)
  const [customers, setCustomers] = useState<any[]>([])
  const [plans, setPlans] = useState<any[]>([])
  const { toast } = useToast()

  useEffect(() => {
    supabase.rpc('expire_subscriptions').then(() => loadSubs())
    loadOptions()
    const ch = supabase.channel('subs-rt')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'subscriptions' }, () => loadSubs())
      .subscribe()
    return () => { supabase.removeChannel(ch) }
  }, [])

  async function loadSubs() {
    const { data } = await supabase
      .from('subscriptions')
      .select('*, user:users!subscriptions_user_id_fkey(name, phone, customer_code), plans:plans!subscriptions_plan_id_fkey(name)')
      .order('created_at', { ascending: false })
    setSubs(data ?? [])
    setLoading(false)
  }

  async function loadOptions() {
    const [c, p] = await Promise.all([
      supabase.from('users').select('id, name, phone').eq('role', 'customer').eq('is_active', true).order('name'),
      supabase.from('plans').select('id, name, items_per_month, monthly_price, quarterly_price, biannual_price, annual_price').eq('is_active', true).order('monthly_price'),
    ])
    setCustomers(c.data ?? [])
    setPlans(p.data ?? [])
  }

  function getPlanPrice(planId: string, duration: string): number {
    const plan = plans.find(p => p.id === planId)
    if (!plan) return 0
    const priceMap: Record<string, number> = {
      monthly: plan.monthly_price,
      quarterly: plan.quarterly_price ?? plan.monthly_price * 3,
      biannual: plan.biannual_price ?? plan.monthly_price * 6,
      annual: plan.annual_price ?? plan.monthly_price * 12,
    }
    return priceMap[duration] ?? 0
  }

  function getPlanItemsLimit(planId: string, duration: string): number {
    const plan = plans.find(p => p.id === planId)
    if (!plan) return 0
    const months = duration === 'monthly' ? 1 : duration === 'quarterly' ? 3 : duration === 'biannual' ? 6 : 12
    return plan.items_per_month * months
  }

  async function handleAdd(e: React.FormEvent) {
    e.preventDefault()
    if (!form.user_id || !form.plan_id) { toast('اختر العميل والباقة', 'error'); return }
    setSaving(true)
    const { data: existing } = await supabase.from('subscriptions').select('id').eq('user_id', form.user_id).eq('plan_id', form.plan_id).eq('status', 'active').maybeSingle()
    if (existing) { setSaving(false); toast('العميل عنده اشتراك نشط في نفس الباقة بالفعل', 'error'); return }
    const totalPaid = getPlanPrice(form.plan_id, form.duration)
    const itemsLimit = getPlanItemsLimit(form.plan_id, form.duration)
    const { error } = await supabase.from('subscriptions').insert({
      user_id: form.user_id,
      plan_id: form.plan_id,
      duration: form.duration,
      status: form.status,
      items_used: 0,
      items_limit: itemsLimit,
      payment_method: form.payment_method,
      total_paid: totalPaid,
      auto_renew: form.auto_renew,
    })
    setSaving(false)
    if (!error) {
      const planName = plans.find(p => p.id === form.plan_id)?.name ?? 'الباقة'
      const durationText = durationLabels[form.duration] ?? form.duration
      const notifTitle = form.status === 'active' ? 'تم تفعيل اشتراكك' : 'تم إنشاء اشتراك جديد'
      const notifBody = form.status === 'active'
        ? `تم تفعيل اشتراكك في باقة ${planName} (${durationText}). يمكنك الآن إنشاء طلباتك.`
        : `تم إنشاء اشتراك في باقة ${planName} (${durationText}). في انتظار التفعيل.`

      await supabase.from('notifications').insert({
        user_id: form.user_id,
        title: notifTitle,
        body: notifBody,
        type: 'system',
        data: { plan_id: form.plan_id },
        sent_at: new Date().toISOString(),
      })

      const { data: userData } = await supabase.from('users').select('fcm_token').eq('id', form.user_id).single()
      if (userData?.fcm_token) {
        fetch('https://exp.host/--/api/v2/push/send', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            to: userData.fcm_token,
            title: notifTitle,
            body: notifBody,
            sound: 'default',
            data: { type: 'subscription' },
          }),
        }).catch(() => {})
      }

      setShowAdd(false); setForm(emptyForm); loadSubs(); toast('تم إضافة الاشتراك بنجاح')
    } else { toast('حدث خطأ: ' + error.message, 'error') }
  }

  async function handleEdit(e: React.FormEvent) {
    e.preventDefault()
    setSaving(true)
    const totalPaid = getPlanPrice(form.plan_id, form.duration)
    const itemsLimit = getPlanItemsLimit(form.plan_id, form.duration)
    const { error } = await supabase.from('subscriptions').update({
      plan_id: form.plan_id,
      duration: form.duration,
      status: form.status,
      items_used: form.items_used,
      items_limit: itemsLimit,
      payment_method: form.payment_method,
      total_paid: totalPaid,
      auto_renew: form.auto_renew,
    }).eq('id', editSub.id)
    setSaving(false)
    if (!error) { setEditSub(null); loadSubs(); toast('تم تعديل الاشتراك') }
    else { toast('حدث خطأ: ' + error.message, 'error') }
  }

  function openEdit(sub: any) {
    setForm({
      user_id: sub.user_id,
      plan_id: sub.plan_id,
      duration: sub.duration,
      status: sub.status,
      items_used: sub.items_used ?? 0,
      items_limit: sub.items_limit ?? 0,
      payment_method: sub.payment_method ?? 'cash',
      total_paid: sub.total_paid ?? 0,
      auto_renew: sub.auto_renew ?? false,
    })
    setEditSub(sub)
  }

  async function deleteSub(id: string) {
    const sub = subs.find(s => s.id === id)
    if (sub?.status === 'active') { toast('لا يمكن حذف اشتراك نشط — قم بإلغائه أولاً', 'error'); return }
    const { data: linkedOrders } = await supabase.from('orders').select('id').eq('subscription_id', id).not('status', 'in', '("delivered","cancelled","refunded")').limit(1)
    if (linkedOrders && linkedOrders.length > 0) { toast('لا يمكن الحذف — يوجد طلبات مرتبطة لم تكتمل بعد', 'error'); return }
    if (!confirm('هل أنت متأكد من حذف هذا الاشتراك؟')) return
    const { error } = await supabase.from('subscriptions').delete().eq('id', id)
    if (!error) { loadSubs(); setDetail(null); toast('تم حذف الاشتراك', 'warning') }
    else { toast('حدث خطأ أثناء الحذف', 'error') }
  }

  async function activateSub(sub: any) {
    const now = new Date()
    const months = sub.duration === 'monthly' ? 1 : sub.duration === 'quarterly' ? 3 : sub.duration === 'biannual' ? 6 : 12
    const endDate = new Date(now)
    endDate.setMonth(endDate.getMonth() + months)

    await supabase.from('subscriptions').update({
      status: 'active',
      start_date: now.toISOString().split('T')[0],
      end_date: endDate.toISOString().split('T')[0],
    }).eq('id', sub.id)

    const planName = sub.plans?.name ?? 'الباقة'
    await supabase.from('notifications').insert({
      user_id: sub.user_id,
      title: 'تم تفعيل اشتراكك',
      body: `تم قبول وتفعيل اشتراكك في باقة ${planName}. يمكنك الآن إنشاء طلباتك.`,
      type: 'system',
      data: { subscription_id: sub.id },
      sent_at: new Date().toISOString(),
    })

    const { data: userData } = await supabase.from('users').select('fcm_token').eq('id', sub.user_id).single()
    if (userData?.fcm_token) {
      fetch('https://exp.host/--/api/v2/push/send', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          to: userData.fcm_token,
          title: 'تم تفعيل اشتراكك ✅',
          body: `تم قبول وتفعيل اشتراكك في باقة ${planName}. يمكنك الآن إنشاء طلباتك.`,
          sound: 'default',
          data: { type: 'subscription', subscription_id: sub.id },
        }),
      }).catch(() => {})
    }

    loadSubs()
    setDetail(null)
    toast('تم تفعيل الاشتراك بنجاح')
  }

  async function rejectSub(id: string) {
    await supabase.from('subscriptions').update({ status: 'cancelled', cancelled_at: new Date().toISOString() }).eq('id', id)
    loadSubs()
    setDetail(null)
    toast('تم رفض الاشتراك', 'warning')
  }

  async function cancelSub(id: string) {
    await supabase.from('subscriptions').update({ status: 'cancelled', cancelled_at: new Date().toISOString() }).eq('id', id)
    loadSubs()
    setDetail(null)
    toast('تم إلغاء الاشتراك', 'warning')
  }

  const allStatuses = ['all', 'pending', 'active', 'cancelled', 'expired']
  const filtered = subs.filter(s => statusFilter === 'all' || s.status === statusFilter)
  const pendingCount = subs.filter(s => s.status === 'pending').length

  const columns = [
