                { label: 'الباقة', value: detail.plans?.name },
                { label: 'الحالة', value: <Badge variant={statusVariant[detail.status]}>{statusLabels[detail.status]}</Badge> },
                { label: 'المدة', value: durationLabels[detail.duration] },
                { label: 'المبلغ', value: `${detail.total_paid ?? '—'} ج.م` },
                { label: 'تاريخ البداية', value: detail.start_date ?? '—' },
                { label: 'تاريخ الانتهاء', value: detail.end_date ?? '—' },
                { label: 'الأيام المتبقية', value: detail.end_date ? `${Math.max(0, Math.ceil((new Date(detail.end_date).getTime() - Date.now()) / 86400000))} يوم` : '—' },
              ].map((item, i) => (
                <div key={i} className="bg-surface-muted/50 rounded-xl p-3">
                  <p className="text-[10px] text-gray-400 mb-0.5">{item.label}</p>
                  <div className="text-sm font-semibold text-gray-800">{item.value}</div>
                </div>
              ))}
            </div>

            {detail.status === 'active' && (
              <div className="bg-surface-muted/50 rounded-xl p-4">
                <div className="flex justify-between items-center mb-2">
                  <span className="text-xs text-gray-500">القطع المستخدمة</span>
                  <span className="text-sm font-bold text-gray-800">{detail.items_used ?? 0} / {detail.items_limit}</span>
                </div>
                <div className="h-2.5 bg-gray-200 rounded-full overflow-hidden">
                  <div className="h-full bg-primary-500 rounded-full transition-all" style={{ width: `${Math.min(100, ((detail.items_used ?? 0) / detail.items_limit) * 100)}%` }} />
                </div>
                <p className="text-[10px] text-gray-400 mt-1.5">متبقي {detail.items_limit - (detail.items_used ?? 0)} قطعة</p>
              </div>
            )}

            <div className="flex gap-2 pt-2">
              {detail.status === 'pending' && (
                <>
                  <button onClick={() => activateSub(detail)}
                    className="flex-1 flex items-center justify-center gap-2 bg-gradient-to-l from-green-500 to-green-600 text-white p-3 rounded-xl font-semibold text-sm hover:shadow-lg transition-all">
                    <Check size={16} /> تفعيل الاشتراك
                  </button>
                  <button onClick={() => rejectSub(detail.id)}
                    className="px-4 py-3 border border-red-200 text-red-500 rounded-xl text-sm font-medium hover:bg-red-50 transition-colors">
                    رفض
                  </button>
                </>
              )}
              {detail.status === 'active' && (
                <button onClick={() => cancelSub(detail.id)}
                  className="px-4 py-3 border border-red-200 text-red-500 rounded-xl text-sm font-medium hover:bg-red-50 transition-colors">
                  إلغاء الاشتراك
                </button>
              )}
              <button onClick={() => deleteSub(detail.id)}
                className="px-4 py-3 border border-red-200 text-red-500 rounded-xl text-sm font-medium hover:bg-red-50 transition-colors flex items-center gap-1">
                <Trash2 size={14} /> حذف
              </button>
            </div>
          </div>
        )}
      </Modal>
    </div>
    </PermissionGate>
  )
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { rateLimit } from '@/lib/rate-limit'
import { requireAdmin } from '@/lib/api-auth'

const supabaseAdmin = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
)

export async function POST(request: NextRequest) {
  const limited = rateLimit(request)
  if (limited) return limited
  const auth = await requireAdmin(request)
  if (auth instanceof NextResponse) return auth
  const body = await request.json()
  const { name, email, password, phone, role, permissions } = body

  if (!email || !password || !name || !role) {
    return NextResponse.json({ error: 'الاسم والإيميل وكلمة المرور والدور مطلوبين' }, { status: 400 })
  }

  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
  if (!emailRegex.test(email)) {
    return NextResponse.json({ error: 'صيغة البريد الإلكتروني غير صحيحة' }, { status: 400 })
  }

  const { data: existing } = await supabaseAdmin.from('users').select('id').eq('email', email).maybeSingle()
  if (existing) {
    return NextResponse.json({ error: 'البريد الإلكتروني مستخدم بالفعل' }, { status: 400 })
  }

  const { data: authData, error: authError } = await supabaseAdmin.auth.admin.createUser({
    email,
    password,
    email_confirm: true,
    user_metadata: { name, role },
  })

  if (authError) {
    console.error('Auth createUser error:', authError.message, authError)
    if (authError.message?.includes('already been registered') || authError.message?.includes('already exists')) {
      const { data: listData } = await supabaseAdmin.auth.admin.listUsers({ perPage: 50 })
      const existingAuth = listData?.users?.find((u: any) => u.email === email)
      if (existingAuth) {
        await supabaseAdmin.auth.admin.updateUserById(existingAuth.id, { password, user_metadata: { name, role } })
        const updates: Record<string, any> = { name, role, email, permissions: permissions || [], is_active: true }
        if (phone) updates.phone = phone
        await supabaseAdmin.from('users').upsert({ id: existingAuth.id, ...updates })
        return NextResponse.json({ success: true, id: existingAuth.id })
      }
    }
    return NextResponse.json({ error: authError.message }, { status: 400 })
  }

  const updates: Record<string, any> = { name, role, email, permissions: permissions || [] }
  if (phone) updates.phone = phone

  await supabaseAdmin.from('users').update(updates).eq('id', authData.user.id)

  return NextResponse.json({ success: true, id: authData.user.id })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { rateLimit } from '@/lib/rate-limit'
import { requireAdmin } from '@/lib/api-auth'

const supabaseAdmin = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
)

export async function POST(request: NextRequest) {
  const limited = rateLimit(request)
  if (limited) return limited
  const auth = await requireAdmin(request)
  if (auth instanceof NextResponse) return auth
  const body = await request.json()
  const { userId, email, password } = body

  if (!userId) {
    return NextResponse.json({ error: 'معرف المستخدم مطلوب' }, { status: 400 })
  }

  const updates: Record<string, any> = {}
  if (email) updates.email = email
  if (password) {
    if (password.length < 6) {
      return NextResponse.json({ error: 'كلمة المرور يجب أن تكون 6 أحرف على الأقل' }, { status: 400 })
    }
    updates.password = password
  }

  if (Object.keys(updates).length === 0) {
    return NextResponse.json({ error: 'لا توجد بيانات للتحديث' }, { status: 400 })
  }

  if (email) {
    const { data: existing } = await supabaseAdmin.from('users').select('id').eq('email', email).neq('id', userId).maybeSingle()
    if (existing) {
      return NextResponse.json({ error: 'البريد الإلكتروني مستخدم بالفعل' }, { status: 400 })
    }
  }

  const { error } = await supabaseAdmin.auth.admin.updateUserById(userId, updates)
  if (error) {
    return NextResponse.json({ error: error.message }, { status: 400 })
  }

  if (email) {
    await supabaseAdmin.from('users').update({ email }).eq('id', userId)
  }

  return NextResponse.json({ success: true })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { rateLimit } from '@/lib/rate-limit'
import { requireAdmin } from '@/lib/api-auth'

const supabaseAdmin = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
)

export async function POST(request: NextRequest) {
  const limited = rateLimit(request)
  if (limited) return limited
  const auth = await requireAdmin(request)
  if (auth instanceof NextResponse) return auth
  const body = await request.json()
  const { name, phone, email, role, tier, vehicle_type, vehicle_number } = body

  if (email) {
    const { data: existing } = await supabaseAdmin.from('users').select('id').eq('email', email).maybeSingle()
    if (existing) {
      return NextResponse.json({ error: 'البريد الإلكتروني مستخدم بالفعل' }, { status: 400 })
    }
  }

  if (phone) {
    if (!/^01[0125]\d{8}$/.test(phone.replace(/\s|-/g, ''))) {
      return NextResponse.json({ error: 'رقم الموبايل غير صحيح — يجب أن يبدأ بـ 01 ويكون 11 رقم' }, { status: 400 })
    }
    const { data: existing } = await supabaseAdmin.from('users').select('id').eq('phone', phone).maybeSingle()
    if (existing) {
      return NextResponse.json({ error: 'رقم الموبايل مستخدم بالفعل' }, { status: 400 })
    }
  }

  const password = Math.random().toString(36).slice(-10) + 'A1!'

  const { data: authData, error: authError } = await supabaseAdmin.auth.admin.createUser({
    email: email || `${Date.now()}@cleano.temp`,
    password,
    email_confirm: true,
    user_metadata: { name, role: role || 'customer' },
  })

  if (authError) {
    return NextResponse.json({ error: authError.message }, { status: 400 })
  }

  const updates: Record<string, any> = { name, role: role || 'customer' }
  if (phone) updates.phone = phone
  if (tier) updates.tier = tier
  if (vehicle_type) updates.vehicle_type = vehicle_type
  if (vehicle_number) updates.vehicle_number = vehicle_number

  await supabaseAdmin.from('users').update(updates).eq('id', authData.user.id)

  return NextResponse.json({ success: true, id: authData.user.id })
}

