import { useState, useRef, useEffect, ReactNode } from 'react'
import { cn } from '@/lib/utils'

interface TooltipProps {
  content: string
  children: ReactNode
  side?: 'top' | 'bottom' | 'left' | 'right'
  className?: string
}

export default function Tooltip({ content, children, side = 'top', className }: TooltipProps) {
  const [show, setShow] = useState(false)
  const [pos, setPos] = useState({ x: 0, y: 0 })
  const triggerRef = useRef<HTMLDivElement>(null)
  const tipRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (!show || !triggerRef.current || !tipRef.current) return
    const tr = triggerRef.current.getBoundingClientRect()
    const tip = tipRef.current.getBoundingClientRect()
    let x = 0, y = 0

    switch (side) {
      case 'top':
        x = tr.left + tr.width / 2 - tip.width / 2
        y = tr.top - tip.height - 6
        break
      case 'bottom':
        x = tr.left + tr.width / 2 - tip.width / 2
        y = tr.bottom + 6
        break
      case 'left':
        x = tr.left - tip.width - 6
        y = tr.top + tr.height / 2 - tip.height / 2
        break
      case 'right':
        x = tr.right + 6
        y = tr.top + tr.height / 2 - tip.height / 2
        break
    }

    x = Math.max(4, Math.min(x, window.innerWidth - tip.width - 4))
    y = Math.max(4, Math.min(y, window.innerHeight - tip.height - 4))

    setPos({ x, y })
  }, [show, side])

  return (
    <>
      <div
        ref={triggerRef}
        onMouseEnter={() => setShow(true)}
        onMouseLeave={() => setShow(false)}
        className={cn('inline-flex', className)}
      >
        {children}
      </div>
      {show && (
        <div
          ref={tipRef}
          className="fixed z-[9999] px-2.5 py-1.5 text-[11px] font-medium text-white bg-navy-900 rounded-lg shadow-lg pointer-events-none whitespace-nowrap"
          style={{ left: pos.x, top: pos.y }}
        >
          {content}
        </div>
      )}
    </>
  )
}

import { createServerClient } from '@supabase/ssr'
import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'

const supabaseAdmin = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
)

const ADMIN_ROLES = ['admin', 'super_admin', 'manager', 'accountant']

export async function requireAdmin(req: NextRequest): Promise<{ userId: string; role: string } | NextResponse> {
  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    { cookies: { getAll() { return req.cookies.getAll() }, setAll() {} } }
  )

  const { data: { session } } = await supabase.auth.getSession()
  if (!session) {
    return NextResponse.json({ error: 'غير مصرح — سجل الدخول أولاً' }, { status: 401 })
  }

  const { data: profile } = await supabaseAdmin.from('users').select('role, is_active').eq('id', session.user.id).single()
  if (!profile || !ADMIN_ROLES.includes(profile.role)) {
    return NextResponse.json({ error: 'غير مصرح — صلاحيات غير كافية' }, { status: 403 })
  }
  if (profile.is_active === false) {
    return NextResponse.json({ error: 'الحساب معطل' }, { status: 403 })
  }

  return { userId: session.user.id, role: profile.role }
}

